window.APP_DATA={"eras":[{"k":"w1","side":"we","n":"古埃及·两河","sub":"约前3000—前500","c":"#4f89a8"},{"k":"w2","side":"we","n":"古希腊","sub":"前500—前146","c":"#4a80a0"},{"k":"w3","side":"we","n":"古罗马","sub":"前146—476","c":"#447797"},{"k":"w4","side":"we","n":"中世纪","sub":"476—1400","c":"#3e6e8e"},{"k":"w5","side":"we","n":"意大利文艺复兴","sub":"1400—1600","c":"#386585"},{"k":"w6","side":"we","n":"法国古典主义","sub":"1600—1750","c":"#325c7c"},{"k":"w7","side":"we","n":"英国风景园","sub":"1700—1850","c":"#2c5373"},{"k":"w8","side":"we","n":"欧美近现代","sub":"1850—","c":"#264a6a"},{"k":"c1","side":"cn","n":"生成期·商周秦汉","sub":"前16世纪—220","c":"#c8763c"},{"k":"c2","side":"cn","n":"转折期·魏晋南北朝","sub":"220—589","c":"#c06e38"},{"k":"c3","side":"cn","n":"全盛期·隋唐","sub":"589—960","c":"#b86634"},{"k":"c4","side":"cn","n":"成熟期一·宋","sub":"960—1271","c":"#b05e30"},{"k":"c5","side":"cn","n":"成熟期二·元明清初","sub":"1271—1736","c":"#a8562c"},{"k":"c6","side":"cn","n":"成熟后期·清中至清末","sub":"1736—1911","c":"#a04e28"}],"stops":[{"id":"w01","seq":1,"day":1,"t":"尼罗河畔的第一座园子","era":"w1","y":-2000,"place":"底比斯","lat":25.7,"lon":32.64,"tags":["古埃及","宅园","宫苑","圣苑","墓园","塔门","方尖碑"],"lead":"西方园林的起点不是观赏，而是活命——在酷热里围出一小片阴凉湿润的绿洲。","pts":[{"h":"为什么从埃及开始","b":"尼罗河是唯一水源，园林只能建在河谷与三角洲。地形平缓少高差，所以埃及园子一律方正、对称、紧凑，与它几何化的美术风格一致。"},{"h":"四种类型","b":"①宅园：贵族私园，高墙挡热浪风沙，宅第在中后部，正门面向河流，入口用神庙式塔门；②宫苑：法老所有，底比斯法老庄园用地近正方形，前广场立两座方尖碑崇拜太阳，宫殿居中央，后有大型石砌水池，可荡舟垂钓；③圣苑（圣林）：神庙四周植树，卡纳克神庙还挖大水池供祭司净身；④墓园：灵魂不灭观下的产物，墓室绘园林壁画，陵周辟游乐空间。"},{"h":"造园要素","b":"水池是核心，多为下沉式、石砌池壁，设台阶联系上下；植物用椰枣、棕榈、无花果、刺槐、埃及榕，行列式间植；葡萄廊架遮阴；花台种虞美人、牵牛、玫瑰、茉莉。早期少用花卉，观赏中心是水景，色彩淡雅。大型皇家庄园把几座小宫殿分散布置，用院墙、栅栏、树木分隔成数个庭园，形成「园中园」。"},{"h":"布局手法","b":"宅第与入口塔门构成明显中轴线，笔直甬道居中，凉亭、水池对称列于两侧。这种「园中园」分隔做法后来在伊斯兰园林中极为常见。"},{"h":"两个深层动因","b":"宗教：太阳神崇拜催生圣苑，来世观催生墓园。技术：农业灌溉推动引水、测量、几何学发展，反过来塑造了规整风格。"}],"q":[{"k":"名词","t":"圣苑（圣林）","a":"古埃及、古巴比伦等地围绕神庙、祭坛种植的林地。祭司在神庙四周的寺庙领地上植树造林，以埃及榕、棕榈等乡土树为主，也有引种外来植物者。卡纳克等大型神庙还开挖水池、以花岗岩或斑岩砌筑驳岸，供祭司祭祀前净身，水中种芦苇睡莲、放养被视为圣物的鳄鱼。圣苑既服务于祭祀，也强化了神殿的肃穆气氛，是西方园林最早的宗教性绿地类型。","kp":"神庙周围＋祭祀功能（2分）／树种与水池细节（2分）／宗教意义（1分）","err":"不要写成「森林公园」。圣苑的核心是神庙＋树林＋祭祀，不是生产性林地。"},{"k":"简答","t":"简述古埃及园林的类型与共同特征","a":"类型有四：宅园、宫苑、圣苑、墓园。共同特征：①相地——只能选尼罗河河谷与三角洲，地形平缓少高差；②布局——方正对称，宅第与塔门构成中轴，甬道居中，凉亭水池对称布置，大园以墙、栅栏、树列分隔成数个庭园；③要素——下沉式水池为核心，行列式种植椰枣、棕榈、无花果、刺槐，葡萄廊架遮阴，花台点缀；④动因——专制王权与宗教信仰催生圣苑与墓园，灌溉技术推动了几何式风格。总体是实用与宗教并重、以水景为观赏中心的规整园林。","kp":"四类型（4分）＋布局与要素（4分）＋动因（2分）","err":"容易只答「有水池有棕榈」，漏掉「四类型」骨架；墓园是最容易被忘的一类。"}]},{"id":"c01","seq":2,"day":1,"t":"囿与台：园林的胚胎","era":"c1","y":-1600,"place":"中原","lat":34.6,"lon":113.6,"tags":["囿","圃","台","沼","灵囿","狩猎","生成期"],"lead":"中国园林不是从「看景」开始的，而是从「圈地养兽」和「筑台望天」开始的。","pts":[{"h":"三个源头概念","b":"①囿：帝王圈围山林、豢养禽兽供狩猎的天然园地，《诗经》「王在灵囿」记周文王之囿，设垣墙、台、沼，是中国园林最早的雏形；②圃：种植蔬菜瓜果苗木的田地，《周礼》「园圃毓草木」，以生产功能为主；③台：夯土高台，用于望气、观天象、通神明，是最早的人工构筑物。"},{"h":"从囿到台榭","b":"商周时「囿」与「台」结合，出现「台榭」——在高台上建屋，既可远眺又可宴饮。春秋战国诸侯竞相筑高台（楚章华台、吴姑苏台），台成为权力与财富的象征。"},{"h":"园林起源的四个条件","b":"①经济：农业剩余使一部分人脱离生产，得以营建与游憩；②政治：王权确立，需要以宏大空间彰显威仪；③思想：神仙思想与「通天」观念，使高台具有宗教意义；④技术：夯土、木构、凿池技术成熟。"},{"h":"为什么说这是「生成期」","b":"这一阶段的园林尚未成为独立的艺术：囿以生产与狩猎为主，台以宗教与政治为主，二者都还不是「为观赏而造」。但「山水」要素（台、沼）已经出现，为后世园林提供了原型。"}],"q":[{"k":"名词","t":"囿","a":"中国古代帝王圈养禽兽、供狩猎游乐的天然园地，是中国园林最早的雏形。商周时期已有「囿」字，甲骨文与《诗经》「王在灵囿」记周文王之囿，设垣墙、台、沼，放养禽兽。其特征是以自然山林水体为主、人工构筑物少，功能上兼有狩猎、祭祀、生产、游赏，并有「与民同乐」的政治意味。春秋战国的台榭、秦汉的苑囿皆由此发展而来，「囿」始终是皇家园林的发端。","kp":"定义（2分）＋灵囿与特征（2分）＋流变（1分）","err":"不要与「圃」混。圃是种植果蔬苗木的生产用地，囿是养兽狩猎的天然园地，两者的关键词完全不同。"},{"k":"简答","t":"简述中国古典园林起源的四个条件","a":"①经济条件：农业剩余产品使一部分人脱离生产劳动，得以从事营建与游憩活动，这是园林产生的前提。②政治条件：王权确立后，统治者需要以宏大的空间彰显威仪与财富，囿与台因此成为权力的物质表现。③思想条件：神仙思想与「通天」观念使高台具有宗教意义，帝王筑台以望气、通神明、求长生。④技术条件：夯土、木构、凿池技术成熟，使大规模营建成为可能。四者共同作用，使「囿」与「台」从单纯的生产与宗教设施，逐步演化为兼具游赏功能的园林雏形。","kp":"经济（2分）＋政治（2分）＋思想（2分）＋技术（2分）＋综合（2分）","err":"不要只答「因为有了皇帝」。四个条件要能默写，这是中国园林起源的标准答案。"}]},{"id":"w02","seq":3,"day":1,"t":"空中花园：台地园的远祖","era":"w1","y":-600,"place":"巴比伦","lat":32.54,"lon":44.42,"tags":["古巴比伦","空中花园","悬园","拱券","猎苑","圣苑"],"lead":"把一座山搬到平原上——层层退台、拱券承重、提水灌溉，这三件事后来支撑了整个意大利台地园。","pts":[{"h":"三种类型","b":"①猎苑：圈养野生动物供狩猎，与中国「囿」性质相近，说明东西方园林起源有相通处；②圣苑：因尊崇树木而在神庙周围成行植树，亚述国王圣那克里布在裸露岩石上凿出深达1.5米的圆形树穴，圣苑占地约1.6公顷；③宫苑：即「空中花园」，又称悬园。"},{"h":"空中花园的真实结构","b":"并非悬在空中，而是金字塔形数层平台堆叠。方形底座边长约140米，台层高约22.5米（与巴比伦城墙等高）。每层边缘有石砌拱形外廊，内为卧室、洞府、浴室；台层覆土种植柑橘类与多层次植物群落，各层以阶梯联系。"},{"h":"三项关键技术","b":"①承重：拱券结构厚重，足以承载深厚土层；②防渗：芦苇、砖、铅皮与种植土层叠压；③灌溉：角隅安置提水辘轳，把河水提升到顶层再逐层下浇，同时形成活泼的跌水景观。"},{"h":"为什么重要","b":"它把「台」「拱」「水」三件事组合在一起：台地解决高差，拱券解决承重，提水解决水源。这正是后世意大利台地园的三大技术前提，所以称「台地园的远祖」。"},{"h":"史料状况","b":"已毁灭殆尽，对其规模结构的了解全部来自古希腊、古罗马史学家著作与考古浮雕，真实面目至今仍有争议——答题时交代这一点，是学术严谨性的加分处。"}],"q":[{"k":"名词","t":"空中花园（悬园）","a":"古巴比伦宫苑，被誉为古代世界七大奇迹之一。它并非悬于空中，而是由金字塔形数层平台堆叠而成的屋顶花园：方形底座边长约140米，台层高约22.5米。每层边缘有石砌拱形外廊，内设卧室、洞府、浴室，台层覆土种植柑橘与多种植物，各层以阶梯联系。技术上以厚重拱券承重，用芦苇、砖、铅皮与土层叠压防渗，在角隅设提水辘轳将河水提升至顶层逐层浇灌，形成跌水。它是台地园的远祖，但原物已毁，认识主要来自古典文献与考古浮雕，真实面貌仍有争议。","kp":"台层结构（2分）＋三项技术（2分）＋意义（1分）","err":"不要说「悬在空中」。必须点出拱券承重、铅皮防渗、辘轳提水这三项，否则拿不到技术分。"},{"k":"论述","t":"为什么说空中花园是意大利台地园的远祖？","a":"一、形式上的连续性。空中花园是「金字塔形数层平台堆叠」，这正是台地园的基本形制——兰特庄园、埃斯特庄园都是四层台地沿山坡叠起。区别只在于前者人工堆筑于平原，后者依天然山坡而建。二、技术上的连续性。台地园要解决三个问题：高差怎么组织、土层怎么承重、水怎么送到高处。空中花园恰好给出三个答案：台层与阶梯解决高差，厚重拱券解决承重，提水辘轳加逐层浇灌解决水源，还顺带产生跌水景观。文艺复兴的意大利造园家做的，就是把这三项技术在真实山坡上重新演绎一遍——埃斯特庄园的「水风琴」「百泉台」本质是提水与跌水的放大。三、观念上的连续性。空中花园为安慰米底王妃对高原家乡的怀念而建（一说），本质是「在平原上造一座山」；台地园同样是在山坡上造一个「人工的自然」，两者都在用几何秩序改写地形。四、差异也要说清：空中花园是孤立的建筑化屋顶花园，台地园是建筑与花园一体化的整体设计，有轴线贯通、有借景、有丛林剧场，这是文艺复兴的推进，不是简单重复。结论：远祖关系成立在「台—拱—水」这套技术母题上，而不是形式抄袭。","kp":"形式连续（4分）＋技术三项（5分）＋观念（3分）＋差异（3分）","err":"只写「都是台地」太浅。必须把拱券承重、提水灌溉、跌水这三条讲透，这才是「远祖」的实质。"}],"img":"hanging"},{"id":"w03","seq":4,"day":1,"t":"希腊：圣林、竞技场与学园","era":"w2","y":-450,"place":"雅典","lat":37.98,"lon":23.73,"tags":["古希腊","圣林","竞技场","学园","柱廊中庭","阿多尼斯园","黄金分割"],"lead":"希腊人把园林从「神的领地」扩展到「人的公共生活」——竞技、讲学、集会，都在树下发生。","pts":[{"h":"五种类型","b":"①圣林：神庙周围林地，荷马时代只是围墙的一部分，后带神苑性质，内有散步道、柱廊、凉亭、座椅，兼祭祀与休憩；②竞技场：多建在山坡，利用地形做看台，与神庙结合，赛会是祭典的一部分，后发展为向公众开放的体育公园；③学园（文人园）：柏拉图、亚里士多德的学校设在园林中，称「阿卡德米亚」，后世欧洲大学校园多源于此；④柱廊中庭（Peristylium）：住宅中央的列柱围合庭院，地面铺砌，置赤陶雕像、盆栽、大理石喷泉，后种植葡萄、柳、榆、柏与花卉；⑤阿多尼斯园：祭祀阿多尼斯的屋顶庭园，在屋顶立塑像、环以种有莴苣茴香麦苗的土钵。"},{"h":"美学的奠基","b":"毕达哥拉斯提出「美是和谐」，探求比例量化，提出黄金分割；亚里士多德强调美的整体性，和谐建立在有机整体概念上。比例与尺度的原则为西方古典主义美学打下基础。"},{"h":"柱廊中庭的演变","b":"最初只是硬质铺地，无栽植，代之以雕像、盆栽、喷泉；随栽培技术进步，中庭内种上葡萄、柳树、榆树、柏树，花卉成片，月季常见，夹竹桃成片种植，并出现收集植物品种的风气——这是「植物园」意识的萌芽。"},{"h":"公共性的意义","b":"希腊的民主政治与自由论争风气，使公共聚会频繁，公共园林比私人庭园更辉煌。从圣林到体育场再到公共园林、文人园，是一条循序渐进的历史过程，后一形式总在前一形式基础上发展。"}],"q":[{"k":"名词","t":"柱廊中庭（Peristylium）","a":"古希腊住宅中央由列柱围合的庭院，是希腊园林影响最深远的类型之一。早期地面仅略事铺砌，不栽花种草，而以赤陶雕像、盆栽、大理石喷泉点缀；随着生活水平与栽培技术进步，中庭内陆续种上葡萄、柳树、榆树、柏树，花卉成片，月季、夹竹桃常见，并出现收集植物品种的风气，布置成花圃形式。柱廊式庭园盛行于希腊城市，被罗马帝国继承发展，并显著影响了欧洲中世纪寺院园林的中庭形式。","kp":"定义与形制（2分）＋演变（2分）＋影响（1分）","err":"不要与「阿多尼斯园」混——一个在住宅中庭，一个在屋顶；柱廊中庭的关键词是「列柱围合」。"},{"k":"简答","t":"古希腊园林有哪几种类型？各自的成因是什么？","a":"①圣林：源于祭祀，神庙四周植树成林，荷马时代仅为围墙一部分，后具神苑性质，兼祭祀与休憩。②竞技场：源于祭典中的运动竞赛，多建在山坡利用地形做看台，与神庙结合，后发展为公众开放的体育公园。③学园（文人园）：哲学家办学于园林，柏拉图、亚里士多德的学校即设于园中，称阿卡德米亚。④柱廊中庭：住宅生活的核心，由列柱围合，从硬质铺地逐步演变为种植庭园。⑤阿多尼斯园：源于祭祀美少年阿多尼斯的习俗，在屋顶立像、环以麦苗土钵，形成屋顶庭园。五类共同反映了希腊「公共生活＋神人同形」的文化性格。","kp":"五类型各1分（5分）＋成因说明（3分）＋总体判断（2分）","err":"最容易漏「阿多尼斯园」和「学园」；五类要能默写全，这是希腊部分的标准骨架。"}]},{"id":"c02","seq":5,"day":1,"t":"秦汉：一池三山定型","era":"c1","y":-104,"place":"长安","lat":34.3,"lon":108.8,"tags":["上林苑","建章宫","太液池","一池三山","兰池宫","神仙思想"],"lead":"秦始皇挖池筑蓬莱，汉武帝在池中放三座仙山——中国皇家园林两千年的空间母题在此定型。","pts":[{"h":"秦：上林苑与兰池宫","b":"秦始皇扩上林苑，引渭水为兰池，池中筑蓬莱山，开「一池三山」之先声。宫苑与都城结合，规模空前。"},{"h":"汉：建章宫太液池","b":"武帝太初元年（前104）建建章宫，太液池中起蓬莱、方丈、瀛洲三山，象征东海神山。这一格局成为皇家园林的固定范式，延续两千年。"},{"h":"上林苑的规模","b":"汉武帝时上林苑周袤三百里，有离宫七十所，昆明池、太液池等水体，兼有狩猎、生产、游赏、军事训练多重功能，是中国历史上最大的皇家园林。"},{"h":"神仙思想与造园","b":"「一池三山」不是简单的模仿自然，而是以有限水面象征无限东海，以三岛象征不可企及的仙山——这是「移天缩地」的第一次实践，也是中国园林写意传统的源头。"},{"h":"汉代私家园林","b":"袁广汉园「东西四里，南北五里」，以石为山、引水为池，是中国最早有记载的私家园林，说明造园已从皇家扩展到富商。"}],"q":[{"k":"名词","t":"一池三山","a":"中国古代皇家园林中以一泓水面象征东海，水中置三岛象征蓬莱、方丈、瀛洲三座仙山的布局模式。源于秦汉神仙思想：秦始皇兰池宫、汉武帝建章宫太液池已有此格局。此后成为皇家园林的固定范式：唐太液池、宋艮岳、明清西苑，清代颐和园昆明湖三岛、圆明园福海三岛皆沿用。它以有限水面造无限意境，体现「移天缩地」的造园智慧，是中国古典园林最具代表性的空间模式与仙苑传统标志。","kp":"定义（2分）＋源流（1分）＋实例（1分）＋意义（1分）","err":"三座仙山名称要写全：蓬莱、方丈、瀛洲。2014年原题作「一池三岛」，与本条同指。"},{"k":"名词","t":"建章宫","a":"西汉武帝太初元年（公元前104年）建于长安城西的大型宫殿园林，与未央宫隔城相望。其「千门万户」，规模宏大；园内北部为太液池，池中起蓬莱、方丈、瀛洲三山，象征东海神山，是「一池三山」皇家格局的典型开端。宫中还有神明台、井干楼、奇华殿等，兼有求仙、朝会、游憩功能。它开创了宫苑内以「太液池＋三神山」为骨架的仙苑格局，直接影响后世颐和园昆明湖三岛、圆明园福海三岛。","kp":"时代与位置（1分）＋太液池一池三山（2分）＋影响（1分）","err":"不要写成唐代大明宫或汉代未央宫。建章宫的关键词是「太液池＋三神山」。"},{"k":"论述","t":"试论神仙思想对中国古典园林空间格局的影响","a":"一、源头：秦汉的神仙思想。秦始皇求长生，在兰池宫池中筑蓬莱山；汉武帝在建章宫太液池中起蓬莱、方丈、瀛洲三山，象征东海神山。这不是对自然的模仿，而是以有限的水面象征无限的东海，以三岛象征不可企及的仙山——「一池三山」由此定型。二、空间模式的固化。此后两千年，「一池三山」成为皇家园林的固定范式：唐太液池、宋艮岳、明清西苑，直至清代颐和园昆明湖三岛、圆明园福海三岛。它提供了中国园林最基本的空间母题——「以水为心、以岛为骨」。三、美学转向：从求仙到写意。汉代的三山是「求仙」的实物，到了唐宋，三山逐渐褪去宗教色彩，变成纯粹的造景手法——「移天缩地」「以小见大」。神仙思想从信仰变成了美学，这是中国园林写意传统的重要来源。四、影响范围的扩展。这一模式不仅用于皇家园林，也渗透到私家园林的「池中置岛」、寺观园林的「放生池」，成为全民族的造园语汇。结论：神仙思想给中国园林提供了第一个「以小喻大」的空间范式，它的意义不在于宗教，而在于确立了「有限中见无限」的审美原则。","kp":"源头（4分）＋模式固化（4分）＋从求仙到写意（4分）＋扩展（2分）","err":"不要只写「一池三山很常见」。核心论点是「从信仰到美学的转化」，这是中国园林写意传统的根源。"}]},{"id":"w04","seq":6,"day":1,"t":"罗马：把希腊的园子放大","era":"w3","y":118,"place":"蒂沃利","lat":41.96,"lon":12.72,"tags":["古罗马","哈德良山庄","洛朗丹","柱廊园","别墅园"],"lead":"罗马人继承了希腊的中庭，又用拱券、穹顶和巨量水源，把它变成可以装下一座城的别墅园。","pts":[{"h":"三种类型","b":"①柱廊园：住宅中庭的罗马版本，规模更大、装饰更豪；②宅园：城市住宅的后院花园；③别墅园：郊野大型庄园，罗马园林的最高成就，洛朗丹别墅、哈德良山庄为代表。"},{"h":"哈德良山庄","b":"罗马皇帝哈德良的离宫，占地约120公顷，位于蒂沃利。它把皇帝游历过的名胜复现于园中：卡诺珀斯运河（仿埃及）、海上剧场、岁序厅、斯多葛画廊。轴线、水景、建筑群自由组合，是古代别墅园的巅峰。"},{"h":"技术与规模","b":"罗马人有拱券、穹顶、混凝土，能造大跨度建筑与大型水渠；城市供水系统（水道桥）让园林可以用大量活水造喷泉、运河、浴场。这是希腊做不到的。"},{"h":"对后世的影响","b":"文艺复兴的意大利别墅园直接以罗马别墅园为范本（尤其是哈德良山庄与普林尼书信中描述的别墅）；台地园的「建筑—花园—自然」序列，源头在罗马。"}],"q":[{"k":"名词","t":"哈德良山庄","a":"古罗马皇帝哈德良在蒂沃利建造的离宫别苑，占地约120公顷，是古代别墅园的巅峰之作。山庄把哈德良游历过的名胜复现于园中：仿埃及的卡诺珀斯运河、海上剧场、岁序厅、斯多葛画廊等，轴线、水景与建筑群自由组合，规模宏大而布局灵活。它依托罗马的拱券、穹顶与城市供水技术，得以大量运用活水造景。文艺复兴时期的意大利别墅园多以它为范本，是连接古代与近代西方园林的关键作品。","kp":"性质与规模（2分）＋复现名胜（2分）＋影响（1分）","err":"不要与「洛朗丹别墅」混；哈德良山庄的关键词是「复现游历名胜」与「120公顷」。"},{"k":"论述","t":"比较古希腊与古罗马园林的异同，并说明罗马的推进在哪里","a":"一、相同处。罗马直接继承希腊：柱廊中庭的形制、圣林与神庙结合的方式、雕塑与喷泉的运用、对几何秩序的偏好，都一脉相承。二、规模与技术的跃升。希腊受地形与技术限制，园子小而精；罗马有拱券、穹顶、混凝土与水道桥，能造大跨度建筑、能把活水引到远处，于是出现120公顷的哈德良山庄、能行船的运河、成组的浴场与喷泉。这是量变到质变：希腊的园子是住宅的附属，罗马的园子可以是一座城。三、功能与观念的扩展。希腊园林的公共性体现在圣林、竞技场、学园；罗马把它推向皇帝与贵族的私享奢华——别墅园是身份与权力的展示，浴场、剧场、图书馆都在园中。四、对后世的分叉影响。希腊的柱廊中庭经罗马传入中世纪寺院中庭，是一条「内向庭院」的线索；罗马的别墅园通向文艺复兴意大利台地园，是一条「外向庄园」的线索。结论：罗马不是简单放大希腊，而是用工程技术把希腊的空间理想变成了可以实施的宏大工程，这是它对西方园林最实质的贡献。","kp":"相同处（3分）＋技术跃升（5分）＋观念扩展（3分）＋两条影响链（3分）","err":"不要写成「罗马抄袭希腊」。核心是「技术使规模跃升」，拱券与水道桥是关键词。"}],"img":"hadrian"},{"id":"c03","seq":7,"day":1,"t":"汉代的私家园林与庄园","era":"c1","y":150,"place":"洛阳","lat":34.62,"lon":112.45,"tags":["私家园林","袁广汉","庄园","东汉","梁冀"],"lead":"当造园的权利从皇帝下移到富商与贵族，中国园林的第二种类型诞生了。","pts":[{"h":"袁广汉园","b":"西汉富商袁广汉在北邙山下筑园，「东西四里，南北五里」，以石为山、引水为池，积沙为洲屿，养奇禽异兽。是中国最早有明确记载的私家园林。"},{"h":"东汉私家园林","b":"东汉贵族梁冀「广开园囿，采土筑山，十里九坂，以象二崤」，规模堪比皇家。说明私家园林在东汉已具备与皇家抗衡的财力与胆量。"},{"h":"庄园经济与园林","b":"汉代庄园经济发达，庄园既是生产单位，也是游憩空间。园林与庄园结合，形成「前宅后园」或「宅园合一」的格局，为后世文人园林提供了原型。"},{"h":"三种类型的雏形","b":"到汉代，皇家园林（上林苑、建章宫）、私家园林（袁广汉园、梁冀园）、寺观园林（白马寺）三类已具雏形，中国古典园林的基本类型格局在此时奠定。"}],"q":[{"k":"名词","t":"私家园林","a":"由贵族、官僚、文人、富商等私人营建，供其居住、游憩、宴客、读书的园林，与皇家园林、寺观园林并列为中国古典园林三大类型。汉代已出现袁广汉园、梁冀园等早期实例；明清以江南苏州、扬州、杭州为盛，北方以北京为代表。特征是规模较小，「小中见大」，以叠山、理水、建筑、花木综合造景，追求「虽由人作，宛自天开」；园主多为文人，园与诗文、书画相融，是中国文人审美理想的物质载体。实例有苏州拙政园、留园、网师园，扬州个园，北京恭王府花园。","kp":"定义与三大类型（2分）＋特征（2分）＋实例（1分）","err":"不要把私家园林与寺观园林混。私家园林的关键词是「私人所有＋文人审美」。"},{"k":"简答","t":"简述汉代园林的成就","a":"①皇家园林达到空前规模：上林苑周袤三百里、离宫七十所，建章宫太液池确立「一池三山」范式；②私家园林兴起：袁广汉园「东西四里，南北五里」，以石为山、引水为池，是中国最早有记载的私家园林；梁冀园「十里九坂，以象二崤」，规模堪比皇家；③寺观园林出现：白马寺等佛寺开始营建园林；④三大类型雏形具备：皇家、私家、寺观三类在此期奠定格局；⑤造园手法进步：叠山（以石为山）、理水（引水为池）、蓄养动物、植物配置等手法趋于成熟。汉代是中国古典园林从「生成」走向「转折」的关键阶段。","kp":"皇家（2分）＋私家（3分）＋寺观（1分）＋类型格局（2分）＋手法（2分）","err":"不要只答「上林苑很大」。汉代的真正成就是「三大类型雏形具备」这一格局性判断。"}]},{"id":"c04","seq":8,"day":1,"t":"魏晋南北朝：园林的转折","era":"c2","y":350,"place":"建康","lat":32.06,"lon":118.8,"tags":["转折期","士人园林","山水诗","玄学","寺观园林","谢灵运"],"lead":"乱世里，文人把目光从朝廷转向山林——园林第一次成了「精神的居所」。","pts":[{"h":"转折的历史条件","b":"①政治：战乱频繁、政权更迭，士人避世隐逸；②思想：玄学兴起，崇尚自然、追求个体自由；③文化：山水诗、山水画兴起，谢灵运《山居赋》、陶渊明田园诗把自然推为审美中心；④经济：庄园经济发达，士族有能力营建别墅。"},{"h":"士人园林的兴起","b":"士大夫经营庄园、别墅，以山水为友。园林从「摹拟神仙」转向「再现自然山水」——这是中国园林史上最重要的一次转向：从写实（模仿具体的神山）转向写意（概括自然的意趣）。"},{"h":"寺观园林的出现","b":"「南朝四百八十寺」，佛寺道观普遍园林化。寺院既是宗教场所，也成为城市公共游憩地——这是中国园林「公共性」的最早形态。"},{"h":"皇家园林的变化","b":"邺城铜雀园（曹操）三台列峙，园囿与宫城结合；洛阳、建康的皇家园林规模缩小，但更注重山水意趣，受士人园林影响明显。"},{"h":"转折的实质","b":"从「以神为本」到「以人为本」，从「摹拟神仙」到「再现自然」，从「皇家独享」到「士人参与」——这三条转变，使中国园林从「生成期」进入「转折期」，为隋唐全盛奠定基础。"}],"q":[{"k":"名词","t":"寺观园林","a":"中国古典园林三大类型之一，指佛寺、道观所属的园林。魏晋南北朝时随佛教兴盛而普及，「南朝四百八十寺」即其盛况。寺院多在名山胜地，以自然山水为骨架，配以殿堂、塔、池、花木；既是宗教活动场所，也向公众开放，成为城市与郊野的公共游憩地。寺观园林的出现使园林从皇家与私家独享扩展到公众，是中国园林「公共性」的最早形态。代表有杭州灵隐寺、苏州寒山寺、北京潭柘寺等。","kp":"定义（2分）＋兴起（2分）＋公共性（1分）","err":"不要只答「寺庙里的花园」。核心是「宗教场所＋公共游憩地」双重属性，这是它区别于皇家与私家园林的关键。"},{"k":"论述","t":"为什么说魏晋南北朝是中国园林的转折期？","a":"一、从「摹拟神仙」到「再现自然」。秦汉园林的核心是「一池三山」——模仿想象中的东海神山，是写实的宗教象征；魏晋士人则把目光投向真实的山林，园林开始概括、提炼自然山水，走向写意。这是中国园林史上最根本的一次转向。二、从「皇家独享」到「士人参与」。秦汉造园的主体是帝王，魏晋则出现大量士人庄园别墅，谢灵运《山居赋》记其始宁墅，「傍山带江，尽幽居之美」；陶渊明的田园诗把自然推为审美中心。造园主体从帝王扩展到士大夫，园林的审美趣味随之文人化。三、从「单一类型」到「三大类型齐备」。皇家园林仍在发展（邺城铜雀园），私家园林（士人庄园）大量出现，寺观园林随佛教兴盛而普及——中国古典园林的三大类型至此齐备。四、思想基础。玄学崇尚自然、追求个体自由，山水诗与山水画兴起，为园林提供了美学理论。五、技术积累。叠山、理水、植物配置的手法在此时趋于成熟，为隋唐全盛奠定基础。结论：魏晋南北朝是中国园林从「神的空间」转向「人的空间」的关键期，它确立了此后一千多年中国园林的写意方向。","kp":"从神仙到自然（4分）＋从皇家到士人（4分）＋三大类型（3分）＋思想与技术（3分）","err":"不要泛泛写「魏晋很乱所以园林变了」。四条转变要一条条立住，尤其「从写实到写意」是核心。"}]},{"id":"c05","seq":9,"day":2,"t":"士人园林与山水诗","era":"c2","y":420,"place":"会稽","lat":30.0,"lon":120.58,"tags":["谢灵运","始宁墅","陶渊明","山居赋","文人园林"],"lead":"诗人开始写山，画家开始画山，于是造园的人开始「造」山——三种艺术在同一时期觉醒。","pts":[{"h":"谢灵运与始宁墅","b":"谢灵运《山居赋》详细记述其在会稽的始宁墅：「傍山带江，尽幽居之美」，园中有山、有水、有田、有圃，是生产与游赏合一的庄园。他第一次把「山居」写成一种审美理想。"},{"h":"陶渊明与田园","b":"「采菊东篱下，悠然见南山」——陶渊明把田园生活诗化，为后世文人园林提供了「归隐」的精神原型。"},{"h":"山水诗与山水画","b":"山水诗在晋宋之际成熟（谢灵运为代表），山水画在南北朝独立成科（宗炳《画山水序》、王微《叙画》）。「诗中有画、画中有诗」的审美理想，为园林的「诗画情趣」奠定基础。"},{"h":"对园林的影响","b":"①立意：园林不再只是游赏场所，而是主人品格与理想的投射；②手法：叠山理水开始讲究「意境」，追求「虽由人作，宛自天开」；③命名：景点题名、楹联匾额开始成为园林的组成部分。"}],"q":[{"k":"名词","t":"文人园林","a":"由文人参与营建或体现文人审美趣味的园林，是中国私家园林的主流。源头在魏晋南北朝的士人庄园别墅，谢灵运始宁墅、陶渊明田园为其精神原型。特征：①规模不大，追求「小中见大」；②以诗画入园，景点题名、楹联匾额富文学意味；③叠山理水讲究意境，追求「虽由人作，宛自天开」；④园主多以园林寄托隐逸之志。唐宋以后成为私家园林的主流，明清以苏州拙政园、留园为代表。","kp":"定义（2分）＋特征（2分）＋源流（1分）","err":"文人园林不等于「文人造的园」。核心是「体现文人审美」——诗画情趣、意境、隐逸之志。"},{"k":"简答","t":"简述魏晋南北朝士人园林的特点","a":"①选址：多在山水秀丽的郊野，依山傍水，如谢灵运始宁墅「傍山带江」。②规模：庄园式，兼有生产（田、圃）与游赏功能。③立意：以园林寄托隐逸之志与个体自由，园成为主人品格的投射。④手法：叠山理水开始追求意境，不再摹拟具体的神山，而是概括自然山水的意趣。⑤文化：与山水诗、山水画同步发展，景点题名、楹联匾额开始成为园林组成部分。⑥影响：确立了此后中国园林的写意方向与文人审美基调。","kp":"选址（1分）＋规模（1分）＋立意（2分）＋手法（2分）＋文化（2分）＋影响（2分）","err":"「生产与游赏合一」是士人庄园的特点，容易漏；它区别于后世纯观赏的私家园林。"}]},{"id":"c06","seq":10,"day":2,"t":"隋唐：全盛期的三大类型","era":"c3","y":700,"place":"长安","lat":34.27,"lon":108.95,"tags":["全盛期","西苑","华清宫","大内御苑","行宫御苑","离宫御苑"],"lead":"皇家、私家、寺观三条线同时到达高点——中国园林的基本格局在唐代定型。","pts":[{"h":"全盛期的判断","b":"隋唐是中国古典园林的全盛期：三大类型（皇家、私家、寺观）并行发展、各成体系，中国古典园林的基本格局在这一时期定型。"},{"h":"皇家园林的三类","b":"①大内御苑：位于宫城之内，如唐长安太极宫、大明宫；②行宫御苑：皇帝出行驻跸之用，如华清宫；③离宫御苑：长期居住的宫苑，如九成宫。三类各有功能与规模。"},{"h":"隋西苑","b":"隋炀帝营西苑，周二百里，以人工叠山理水摹拟天下山水，海中有三神山。皇家园林的写意化倾向开始萌发。"},{"h":"唐华清宫","b":"骊山温泉行宫，玄宗时极盛。以天然山水为骨架，宫苑结合，是唐代离宫御苑的代表。"},{"h":"写意的萌芽","b":"从秦汉「模仿自然」的神仙山水，转向概括、提炼自然山水，写意山水园开始萌芽——这是全盛期最重要的转折。"}],"q":[{"k":"简答","t":"简述中国古典园林全盛期的主要成就","a":"①园林类型体系趋于完备：皇家、私家、寺观三大类型并行发展、各成体系，基本格局定型。②皇家园林气派宏大：形成大内御苑、行宫御苑、离宫御苑三类，以长安、洛阳为中心，如西苑、华清宫、九成宫，「一池三山」格局被继承并赋予新的山水意趣。③私家园林文人化起步：士大夫直接参与造园，王维辋川别业、白居易履道坊宅园为代表，讲究「中隐」之趣。④由写实转向写意：从秦汉模仿自然的神仙山水，转向概括提炼自然山水，写意山水园萌芽。⑤寺观园林普及：佛寺道观普遍园林化，成为城市公共游憩空间。⑥技术与著作成熟，并影响日本、朝鲜。","kp":"类型体系（2分）＋皇家（2分）＋私家（2分）＋写意转向（2分）＋寺观（1分）＋影响（1分）","err":"六点要答全。「由写实转向写意」是全盛期最重要的判断，漏掉这一点，答案就只是罗列。"},{"k":"名词","t":"大内御苑","a":"唐代皇家园林的一类，指位于宫城之内的御苑，与行宫御苑、离宫御苑并称。大内御苑依附于宫殿，供皇帝日常游憩，如唐长安太极宫、大明宫内的苑囿。其特点是位置在宫城之内、规模受宫城限制、与政治空间紧密结合；「一池三山」的格局被继承，但更注重山水意趣。三类御苑的分化，标志着唐代皇家园林体系的成熟。","kp":"定义（2分）＋实例（2分）＋意义（1分）","err":"要与「行宫御苑」「离宫御苑」分清：大内在宫城内，行宫是出行驻跸，离宫是长期居住。"}]},{"id":"c07","seq":11,"day":2,"t":"辋川别业：文人园林的起点","era":"c3","y":750,"place":"蓝田","lat":34.1,"lon":109.3,"tags":["王维","辋川别业","文人园林","中隐","辋川集","诗画入园"],"lead":"王维在终南山下买了一块山谷，给它二十个景点各写一首诗——园林从此可以「读」。","pts":[{"h":"辋川别业","b":"王维晚年得宋之问蓝田别墅，改筑辋川别业。因山谷地形造景，有孟城坳、华子冈、文杏馆、斤竹岭、鹿柴、竹里馆、辛夷坞等二十景，与裴迪各赋诗，编为《辋川集》。"},{"h":"文人园林的起点","b":"辋川别业是文人自建山居别墅的典范：①主人是诗人画家，园以诗意立意；②景点命名与题咏结合，园可「读」；③以自然山水为骨架，少加人工；④园成为主人精神世界的投射。"},{"h":"「中隐」之趣","b":"白居易提出「中隐」——既不做隐士也不做朝官，而在城市或近郊的宅园中求得精神自由。履道坊宅园是其实践：宅园合一，以水为中心，竹木环绕。这成为后世文人园林的基本模式。"},{"h":"诗画入园","b":"王维是南宗山水画之祖，苏轼评「诗中有画，画中有诗」。他把画理用于造园，使园林的「意境」第一次有了理论支撑。"}],"q":[{"k":"名词","t":"辋川别业","a":"唐代诗人王维在蓝田辋川营建的山居别墅，是文人园林的起点。王维得宋之问旧墅后改筑，因山谷地形造景，有孟城坳、华子冈、文杏馆、鹿柴、竹里馆、辛夷坞等二十景，与裴迪各赋诗编为《辋川集》。其特征：主人是诗人画家，园以诗意立意；景点命名与题咏结合，园可「读」；以自然山水为骨架，少加人工；园成为主人精神世界的投射。它标志着中国园林从「摹拟自然」走向「以园寄情」，为后世文人园林提供了范式。","kp":"主人与地点（2分）＋二十景与辋川集（2分）＋意义（1分）","err":"不要与「履道坊宅园」混。辋川是山居别墅（郊野），履道坊是城市宅园，两者代表文人园林的两种形态。"},{"k":"名词","t":"中隐","a":"唐代白居易提出的处世与造园观念。指既不做遁迹山林的「小隐」，也不做身居朝市的「大隐」，而在城市或近郊的宅园中求得精神自由——「似出复似处，非忙亦非闲」。其实践是洛阳履道坊宅园：宅园合一，以水为中心，竹木环绕。这一观念使文人不必远离城市即可获得山林之趣，成为后世文人园林的基本模式，直接影响宋代「城市山林」的造园理想。","kp":"定义（2分）＋实践（2分）＋影响（1分）","err":"「中隐」的关键是「不必远离城市」，这与「归隐山林」不同，是理解城市宅园兴起的关键。"}]},{"id":"w05","seq":12,"day":2,"t":"修道院：把园子关进墙里","era":"w4","y":820,"place":"圣加尔","lat":47.42,"lon":9.38,"tags":["中世纪","修道院庭园","圣高尔","柱廊中庭","药草园","菜园"],"lead":"基督教禁欲主义把园林从享乐场所变成了生产设施——但它保留了中庭这个空间原型。","pts":[{"h":"圣高尔修道院平面","b":"9世纪初绘于瑞士康斯坦斯湖畔，占地约1.7公顷，一幅820—830年间本尼狄克派僧侣绘制的平面图详尽描绘了修道院格局，17世纪才在教堂图书馆被重新发现。全院士三部分：①中央教堂、僧侣用房、院长室，中有柱廊式中庭园，十字交叉园路当中有水池，周围四块草地；②南面与西面为畜舍、仓库、食堂、厨房、工场作坊；③北面为医院、僧房、药草园、菜园、果园及墓地。"},{"h":"中庭的形制","b":"教堂与僧房围合的中庭，四周一圈柱廊，墙上绘圣经故事壁画。与希腊罗马的楣式柱廊不同，中世纪多用拱券式，且柱子架在矮墙上如栏杆，只在中庭四边正中或四角留通道——目的是保护柱廊后面的壁画。中庭以十字形或对角线小径分成四块，正中置喷泉、水池或水井，供僧侣净手。"},{"h":"实用园的类型","b":"以采摘花卉为主的花园、提供水果干果的果园、供时令蔬菜香草的菜园、由医生或药剂师亲自管理的药草园，都是不可缺少的部分。这是寺院自给自足要求的产物，也促进了中世纪欧洲园艺事业的发展。"},{"h":"熙笃会的差异","b":"熙笃会清规最严格，僧侣过孤独沉默的生活，因此除中庭外，每处僧房都有单独小庭院，既是个人小天地，又是园艺劳动场所。克勒尔蒙特修道院是典型实例。"}],"q":[{"k":"名词","t":"修道院庭园","a":"中世纪欧洲园林的两种主要形式之一（另一种是城堡庭园）。以圣高尔修道院平面为代表：教堂与僧房围合成中庭，四周环以拱券式柱廊，廊墙绘圣经壁画；中庭以十字形或对角线小径分成四块草地，正中设喷泉、水池或水井供僧侣净手。中庭之外还有药草园、菜园、果园与墓地。它起源于寺院自给自足的实用需求，保留了古希腊罗马柱廊中庭的空间原型，是欧洲中世纪园林的核心类型，也孕育了后世花坛的雏形。","kp":"形制（2分）＋附属园地（2分）＋历史地位（1分）","err":"不要只写「修道院里有花园」。必须点出「柱廊围合的中庭＋十字园路＋中心水池」这套形制。"},{"k":"简答","t":"简述中世纪修道院庭园的布局与功能","a":"布局：以教堂与僧房围合的中庭为核心，四周环拱券式柱廊，廊墙绘圣经故事；中庭用十字形或对角线小径分成四块草地，正中设喷泉、水池或水井。柱廊与中庭之间以矮墙栏杆分隔，只在四边正中或四角留通道，以保护壁画。功能：①宗教——净手、冥想、读经；②生产——药草园由医生或药剂师管理，菜园供时令蔬果，果园提供水果干果，花圃采摘花卉；③生活——僧房外的小庭院供个人园艺劳动。整体反映寺院自给自足的经济结构与禁欲主义的宗教生活。","kp":"布局形制（5分）＋功能三类（5分）","err":"容易漏掉「矮墙栏杆分隔是为了保护壁画」这个细节，这是区别于希腊罗马柱廊园的关键。"}],"img":"stgall"},{"id":"c10","seq":13,"day":2,"t":"沧浪亭与独乐园：文人园的两副面孔","era":"c4","y":1044,"place":"苏州","lat":31.3,"lon":120.62,"tags":["沧浪亭","苏舜钦","独乐园","司马光","城市山林","洛阳名园记"],"lead":"一个把水留在园外，一个把山藏在城里——宋人用两种办法在城市里造山林。","pts":[{"h":"沧浪亭","b":"苏舜钦贬官后所筑，现存苏州最古老的园林。以水环园、复廊借景，「崇阜广水」而不设围墙，是宋代写意山水园的实例。「沧浪」取《楚辞·渔父》「沧浪之水清兮，可以濯吾缨」，寄寓高洁自守。"},{"h":"独乐园","b":"司马光洛阳宅园，面积小、布局简，以「读书堂」「弄水轩」「见山台」等七景寄托独乐之志。司马光在洛阳十五年编《资治通鉴》，园是其精神居所。"},{"h":"洛阳名园记","b":"李格非撰，记洛阳名园十余处，多为士大夫宅园。提出「洛阳之盛衰，候于园圃之废兴」，把园林兴废与国运民生相联系，是研究宋代私家园林最直接的文献。"},{"h":"城市山林","b":"宋代城市宅园的核心理想——在城市中营造山林之趣。手法有：叠山（假山代真山）、理水（小池代江湖）、借景（借寺塔、远山）、题名（以名点景）。"}],"q":[{"k":"名词","t":"沧浪亭","a":"北宋苏舜钦贬官后于苏州所筑的私家园林，现存苏州最古老的园林。以水环园、复廊借景，「崇阜广水」而不设围墙，是宋代写意山水园的实例。「沧浪」取《楚辞·渔父》「沧浪之水清兮，可以濯吾缨」，寄寓主人高洁自守之志。其「以水环园、不设围墙」的手法，把园外的水与园内的山连成一体，是「借景」与「城市山林」理想的早期典范，对后世苏州园林影响深远。","kp":"主人与地点（2分）＋手法（2分）＋意义（1分）","err":"沧浪亭的关键词是「以水环园、不设围墙」，这与后来苏州园林「高墙深院」的模式不同，是它的独特处。"},{"k":"名词","t":"洛阳名园记","a":"北宋李格非（李清照之父）所著园林专著，一卷，记述洛阳城内外的名园十余处。逐园记其位置、布局、景物与花木，如富郑公园、独乐园、水北胡氏园、苗帅园，所记多为士大夫宅园，以水景、竹木、台榭取胜。其价值在于：它是研究宋代私家园林最直接、最可靠的文献，与《园冶》《长物志》同为园林史必读书。李格非并提出「洛阳之盛衰，候于园圃之废兴」，把园林兴废与国运民生相联系，具有深刻的政治批判意味。","kp":"作者与体例（2分）＋内容与实例（2分）＋文献价值（1分）","err":"作者是李格非，不是李诫、李渔，也不是李清照本人；书名不要写成《洛阳伽蓝记》（那是北魏杨衒之记佛寺的书）。"}]},{"id":"c08","seq":14,"day":2,"t":"宋代：写意山水园的成熟","era":"c4","y":1100,"place":"开封","lat":34.8,"lon":114.31,"tags":["宋代","写意","文人园林","简远疏朗","东京","临安"],"lead":"宋人把园林从「造得大」变成「造得妙」——山水不再模仿，而是被概括成一种趣味。","pts":[{"h":"宋代园林的总特征","b":"写意山水园成熟。由写实转向写意，「小中见大」「咫尺山林」，重视意境与理趣；借景、对景、框景、题名点景广泛运用。"},{"h":"文人园林的兴盛","b":"宋代重文轻武，士大夫阶层壮大，文人园林成为主流。审美趣味从唐代的宏丽转向「简远、疏朗、雅致、天然」。"},{"h":"东京与临安","b":"北宋东京（开封）是园林最集中的城市，《洛阳名园记》记洛阳名园十余处；南宋临安（杭州）以西湖为中心，形成「西湖十景」的公共游赏格局。"},{"h":"寺观与公共园林","b":"宋代寺观园林普及，且多向公众开放；西湖、鉴湖等成为公共游赏地，园林的公共性增强。"},{"h":"辽金园林","b":"辽、金继承唐宋传统，营建皇家园林（如金中都的琼华岛），为元代以降的北京园林奠定基础。"}],"q":[{"k":"名词","t":"宋代文人园林","a":"宋代以文人审美为主导的私家园林，是中国古典园林成熟期（一）的主流。特征可概括为四点：①简远——布局疏朗、景物简约，以少胜多，追求「言有尽而意无穷」；②疏朗——空间开敞通透，水面与庭院大量留白，建筑密度低；③雅致——重文化品位，以竹梅松荷石为题，讲求书卷气，排斥富丽俗艳；④天然——因借自然、少加雕琢，叠山理水追求山野之趣。写意手法成熟，「小中见大」「咫尺山林」，借景、对景、框景、题名点景广泛运用。代表有司马光独乐园、苏舜钦沧浪亭、沈括梦溪园。","kp":"四点特征（4分）＋写意手法（3分）＋代表实例（3分）","err":"「简远、疏朗、雅致、天然」八个字要能默写，这是宋代文人园林的标准答案。"},{"k":"论述","t":"试论宋代为什么成为中国古典园林的成熟期","a":"一、写意手法的成熟。秦汉摹拟神仙、魏晋再现自然，到宋代则「概括、提炼」自然——「一拳代山、一勺代水」，山水不再是模仿对象，而是被抽象成一种趣味。这是中国园林美学最根本的成熟标志。二、文人阶层的壮大。宋代重文轻武，士大夫成为造园主体，园林的审美从唐代的宏丽转向「简远、疏朗、雅致、天然」，书卷气取代了富丽气。三、理论与批评的出现。《洛阳名园记》不仅记录名园，更提出「洛阳之盛衰，候于园圃之废兴」，把园林与国家命运相联系；郭熙《林泉高致》提出「可行、可望、可游、可居」，为园林提供了美学标准。四、技术与手法的完备。叠山（艮岳）、理水、建筑（亭台楼阁）、植物配置四大要素全面成熟，借景、对景、框景、障景等手法定型。五、类型的扩展。皇家（艮岳）、私家（独乐园、沧浪亭）、寺观、公共（西湖）四类并盛，园林的社会覆盖面扩大。结论：宋代不是「造得更大」，而是「造得更妙」——它完成了从「写实」到「写意」的转变，确立了中国园林此后八百年的美学方向。","kp":"写意成熟（4分）＋文人阶层（3分）＋理论（3分）＋技术（4分）＋类型（2分）","err":"不要只写「宋代园林很多」。核心论点是「写意手法的成熟」，把「一拳代山、一勺代水」讲透，比罗列名园更有分。"},{"k":"名词","t":"写意山水园","a":"以自然山水为蓝本，经过概括、提炼、典型化，用「一拳代山、一勺代水」的写意手法再现山水的园林类型。它成熟于宋代，与秦汉「摹拟神仙」的写实山水、魏晋「再现自然」的过渡形态相区别。特征：①不求形似而求神似，以少胜多；②小中见大，在有限空间内营造「咫尺山林」；③重视意境与理趣，借景、对景、框景、题名点景广泛运用；④与诗画相通，园可「读」。代表作有艮岳、沧浪亭、独乐园。它是中国古典园林最本质的审美特征。","kp":"定义（2分）＋与前后期的区别（2分）＋特征（1分）","err":"写意山水园的关键是「写意」——不是模仿自然，而是概括自然。要与秦汉的「写实」对举着答。"}]},{"id":"c09","seq":15,"day":2,"t":"艮岳：叠山的巅峰","era":"c4","y":1117,"place":"开封","lat":34.8,"lon":114.31,"tags":["艮岳","宋徽宗","花石纲","叠山","万岁山","寿山"],"lead":"宋徽宗用全国的石头堆了一座山，五年后这座山随着北宋一起灭亡。","pts":[{"h":"基本事实","b":"北宋徽宗政和七年至宣和四年（1117—1122）建于东京汴梁宫城东北，初名万岁山，后改名艮岳（艮为八卦东北方位）。徽宗亲自主持，梁师成、朱勔经办「花石纲」，从江南采运太湖石、奇花异木。"},{"h":"布局","b":"「左山右水」，以万岁山为主峰，寿山、万松岭为辅，山势「括天下之美，藏古今之胜」，有瀑布、洞壑、置石与建筑四十余处。"},{"h":"叠山手法","b":"以土带石、先土后石，主峰万岁山高九十步。峰峦、洞壑、瀑布、蹬道俱全，「山在园中、园在山中」，是中国叠山艺术的最高峰。"},{"h":"历史命运","b":"花石纲激化民怨，成为方腊起义的导火索之一；靖康之变后艮岳渐毁。园林的兴废与国运相连，这正是《洛阳名园记》所说的「园圃之废兴」。"}],"q":[{"k":"名词","t":"艮岳","a":"北宋徽宗政和七年至宣和四年（1117—1122）建于东京汴梁宫城东北的皇家园林，初名万岁山，后改名艮岳（艮为八卦东北方位）。徽宗亲自主持，梁师成、朱勔经办「花石纲」，从江南采运太湖石、奇花异木。布局「左山右水」，以万岁山为主峰，寿山、万松岭为辅，山势「括天下之美，藏古今之胜」，有瀑布、洞壑、置石与建筑四十余处。叠山以土带石、先土后石，主峰高九十步，「山在园中、园在山中」，代表宋代写意山水园的最高成就，也是中国叠山艺术的巅峰。花石纲激化民怨，靖康之变后渐毁。","kp":"时代与名称由来（2分）＋花石纲与布局（2分）＋历史地位（1分）","err":"「艮」是八卦方位（东北），由此得名，不要写成随意命名。花石纲的直接后果是民怨与靖康之变的背景。"},{"k":"简答","t":"简述艮岳的艺术特征","a":"①总体格局「左山右水」：以万岁山为主峰居左，寿山、万松岭为辅，水面居右，山环水抱。②叠山手法：以土带石、先土后石，主峰万岁山高九十步，峰峦、洞壑、峡谷、蹬道俱全，「山在园中、园在山中」。③理水：引景龙江水入园，形成瀑布、溪涧、池沼的完整水系，与山体穿插。④建筑与置石：建筑四十余处，依山就势；置石以太湖石为主，峰石奇秀。⑤意境：以「括天下之美，藏古今之胜」为追求，把天下名山胜景浓缩于一园，是写意山水的极致。⑥历史地位：中国叠山艺术的最高峰，代表宋代写意山水园的最高成就。","kp":"格局（2分）＋叠山（3分）＋理水（2分）＋建筑置石（2分）＋地位（1分）","err":"「左山右水」是艮岳的骨架，必须写；「以土带石、先土后石」是叠山手法的关键词。"}]},{"id":"w06","seq":16,"day":2,"t":"城堡与结园：世俗园林的萌芽","era":"w4","y":1300,"place":"巴黎","lat":48.85,"lon":2.35,"tags":["中世纪","城堡庭园","结园","迷园","绿篱","栅栏"],"lead":"战乱催生了城堡，城堡的高墙里长出了西方第一批「为了好看」的花园。","pts":[{"h":"城堡庭园","b":"中世纪初期战乱频繁，王公贵族在府邸周围构筑防御工事，出现城堡形式：塔楼与雉堞墙是时代特征，多建在山顶，绕以木栅土墙与内外壕沟。13世纪后战乱渐平、东方影响日盛，享乐思想增强，城堡结构转向开敞宜居的宅邸。"},{"h":"庭园布局","b":"从细密画可见：果园围绕高大石墙及壕沟，只有一扇小门出入；园内以木格栅分隔空间，充满月季薄荷清香的小径引向小牧场，草地中央有装饰铜狮的盘式叠泉；人们在散生雏菊的草地上载歌载舞。修剪整形的果木、花坛、喷泉流水、放养的小宠物，营造出田园牧歌般的情趣。"},{"h":"结园（Knot Garden）","b":"以低矮绿篱组成装饰图案的花坛，或为几何图形，或呈鸟兽纹章。分两种：绿篱图案中填以彩色砂石、土壤、碎砖的称开放型结园；图案中种植花卉的称封闭型结园。结园与花圃是后世欧洲花坛的雏形。"},{"h":"迷园与要素","b":"迷园以绿篱构成迷宫，兼具游乐性与宗教象征（朝圣之路）。围墙是中世纪庭园最常见的分隔元素：外墙用石、砖、灰泥砌筑，内部隔墙多用编织栅栏、木桩栅栏、栏杆、花格墙、树篱；常依墙砌土台铺草坪作坐凳；凉亭与棚架是主要建筑小品，与藤本植物结合，起遮阴与装饰作用。"}],"q":[{"k":"名词","t":"结园","a":"中世纪欧洲以低矮绿篱组成装饰图案的花坛类型，图案或为几何图形，或呈鸟兽、纹章等样式。分两种：在绿篱构成的图案中填以彩色砂石、土壤、碎砖的称开放型结园；在图案中种植花卉的称封闭型结园。它由过去的菜畦演变而来，与花圃同为后世欧洲花坛的雏形。结园的出现标志着中世纪庭园从纯实用转向观赏，是世俗园林萌芽的重要标志。","kp":"定义（2分）＋两种类型（2分）＋意义（1分）","err":"不要与「迷园」混。结园是图案花坛，迷园是绿篱迷宫，两者常同时出现在城堡庭园中。"},{"k":"简答","t":"简述中世纪城堡庭园的特点","a":"①选址与防卫：多建在山顶，绕以木栅土墙与内外壕沟，塔楼与雉堞墙是时代特征；13世纪后转向开敞宜居的宅邸。②空间分隔：外墙用石、砖、灰泥，内部用编织栅栏、木桩栅栏、花格墙、树篱分隔，常依墙砌土台铺草坪作坐凳。③造园要素：果园、草地、盘式叠泉、修剪整形的果木、结园、迷园、凉亭与棚架，放养小宠物。④气氛：充满月季薄荷香气的小径、散生雏菊的草地，营造田园牧歌式的情趣。⑤性质：从纯实用转向观赏游乐，是世俗园林的萌芽。","kp":"防卫特征（2分）＋分隔手法（3分）＋要素（3分）＋性质判断（2分）","err":"容易只写「有城堡有花园」。要突出「从防御性转向享乐性」这条演进线索。"}]},{"id":"w07","seq":17,"day":3,"t":"意大利台地园：把山坡变成舞台","era":"w5","y":1500,"place":"佛罗伦萨","lat":43.77,"lon":11.25,"tags":["文艺复兴","台地园","阿尔伯蒂","相地选址","府邸位置","植坛"],"lead":"人文主义者逃出城市、上山建别墅——于是西方园林第一次有了「俯瞰」这个动作。","pts":[{"h":"为什么是意大利","b":"文艺复兴时期人文主义者向往罗马人的田园生活，渴望西塞罗式的乡居情趣，纷纷涌向风景秀丽、环境宜人的城郊乡村营造别墅庄园。意大利台地园的特征就是从这些别墅庄园中产生的。"},{"h":"相地选址","b":"16世纪后半叶的意大利庄园多建在郊外丘陵坡地上，在府邸前留有开阔可供眺望的远景。为营造稳定均衡的庭园空间，园林顺山势辟成多个台层。造园家偏爱地形起伏大的园址，善于利用地形变化创造激动人心的效果——台地布局与地形紧密结合，花园覆盖在山坡上，「就像大地的衣服一样贴切」。"},{"h":"府邸位置的三情况","b":"府邸是庄园主体建筑，也是观赏四周景色的制高点。①教皇的庄园：府邸往往位于最高处，雄伟壮观，控制全园，体现教皇至高无上的权力；②置于中间台层：前后花园环抱，建筑易融入花园，显得亲近随和；③规模较大且地形平缓的大型庄园：府邸设在底层台地上，接近出入口，交通便捷，临近城市的庄园多如此。"},{"h":"借景与几何","b":"由于庄园规模通常不大，有必要引入园外自然景色，通过借景开阔视野、扩大空间感。庄园设计采用严谨对称的几何构图，并利用过渡与渐变手法，使整形式园林与园外自然相互渗透，达到对立统一的艺术高度。"},{"h":"理论的源头","b":"阿尔伯蒂《论建筑》提出别墅选址与构图原则：选址要利于健康、有良好视野；建筑与花园应统一构图。这为台地园提供了理论基础。"}],"q":[{"k":"名词","t":"意大利台地园","a":"文艺复兴时期意大利别墅庄园的典型形式。多建于郊外丘陵坡地，顺山势辟成多个台层，府邸居于制高点或中间台层，前有开阔的眺望远景；采用严谨对称的几何构图，以中轴串联各台层，配植坛、喷泉、台阶、雕像与丛林剧场；由于规模不大，常以借景引入园外自然，并通过过渡与渐变手法使规整园林与自然相互渗透。它体现了人文主义者对罗马田园生活的追慕，是西方规则式园林的第一个高峰。","kp":"台地布局（2分）＋几何构图与要素（2分）＋借景与意义（1分）","err":"台地园不等于「有台阶的园子」。核心是「依山分层＋中轴贯通＋借景园外」三件事。"},{"k":"论述","t":"试论意大利台地园形成的条件与基本特征","a":"一、形成的条件。①思想：文艺复兴人文主义向往罗马人的田园生活与西塞罗式乡居情趣，贵族与教会人士纷纷到城郊建别墅；②地理：意大利多丘陵，城郊山坡提供了天然高差，造园家偏爱起伏大的园址；③技术：古罗马的拱券、水道技术被重新掌握，能解决台地挡土与引水；④理论：阿尔伯蒂《论建筑》提出选址、视野与统一构图的原则。二、基本特征。①相地：建于丘陵坡地，府邸前留眺望远景，顺山势辟多级台地，台地与地形紧密结合，「像大地的衣服」；②布局：府邸居制高点或中间台层（教皇庄园居最高处体现神权，临近城市者居底层便于交通），中轴串联各台层，严谨对称；③要素：植坛、喷泉、跌水、台阶、雕像、丛林剧场、柑橘园；④手法：以借景引入园外自然，用过渡与渐变使规整园林与自然相互渗透。三、历史意义。它第一次系统解决了「如何在有高差的地形上造园」这个命题，把建筑、花园、远景组织成连续的视觉序列，为法国古典主义园林提供了直接的技术与美学基础。","kp":"形成条件四项（6分）＋基本特征四项（8分）＋历史意义（2分）","err":"不要只答「台地园很美」。必须讲清「为什么意大利能产生台地园」——丘陵地形＋人文主义＋罗马技术三条缺一不可。"}]},{"id":"w08","seq":18,"day":3,"t":"文艺复兴初期：望景楼与美第奇","era":"w5","y":1500,"place":"罗马","lat":41.9,"lon":12.45,"tags":["望景楼","布拉曼特","美第奇","菲耶索勒","卡雷吉"],"lead":"台地园的第一个样板在梵蒂冈的山坡上——布拉曼特用两层柱廊把宫殿和花园缝在一起。","pts":[{"h":"望景楼花园","b":"文艺复兴初期台地园的起点，布拉曼特设计。以双层柱廊连接宫殿与花园，中轴、台阶、植坛的雏形在此确立。它第一次把「建筑—台地—远景」组织成连续的视觉序列。"},{"h":"美第奇家族诸园","b":"美第奇家族在菲耶索勒、卡雷吉等地建园，以植坛、泉池、露台为主，尚未形成纵向轴线，是台地园的前身。菲耶索勒美第奇庄园建于山坡，可俯瞰佛罗伦萨，已具台地雏形。"},{"h":"初期特征","b":"①仍以实用为主，果园、菜园占相当比重；②开始强调选址的景观价值，注重眺望；③露台、台阶、植坛、泉池等要素逐步定型；④轴线尚未贯穿全园，各台层相对独立。"},{"h":"过渡到中期","b":"16世纪后半叶，随着造园经验积累与工程技术进步，台地园走向成熟：轴线贯通、跌水成组、丛林剧场出现，代表是埃斯特、兰特、法尔奈斯三大庄园。"}],"q":[{"k":"名词","t":"望景楼花园","a":"文艺复兴初期台地园的起点，由布拉曼特设计，位于梵蒂冈。它以双层柱廊连接宫殿与花园，把中轴、台阶、植坛等要素组织成连续的视觉序列，第一次系统解决了建筑与花园之间的过渡问题。它标志着西方园林从「建筑附属的庭园」向「建筑与花园一体化的庄园」转变，为16世纪意大利台地园的成熟奠定了形制基础。","kp":"位置与设计者（2分）＋形制贡献（2分）＋历史地位（1分）","err":"不要与「法尔奈斯庄园」混。望景楼的关键词是「双层柱廊连接宫殿与花园」。"},{"k":"简答","t":"简述意大利文艺复兴初期园林的特点","a":"①选址：开始重视景观价值，多建于可俯瞰城市的山坡，注重眺望。②布局：以露台、台阶、植坛、泉池为主，各台层相对独立，纵向轴线尚未贯穿全园。③要素：植坛、泉池、露台、雕像初步定型。④功能：仍以实用为主，果园、菜园占相当比重。⑤代表：望景楼花园（布拉曼特设计，双层柱廊连接宫殿与花园）、菲耶索勒与卡雷吉的美第奇庄园。⑥地位：台地园的前身，为16世纪成熟期奠定形制基础。","kp":"选址（1分）＋布局（2分）＋要素（2分）＋功能（2分）＋代表（2分）＋地位（1分）","err":"容易把初期和中期混为一谈。初期的标志是「轴线未贯通、各台层独立」，中期才轴线贯通、跌水成组。"}],"img":"farnese"},{"id":"w09","seq":19,"day":3,"t":"埃斯特庄园：水之园","era":"w5","y":1550,"place":"蒂沃利","lat":41.96,"lon":12.72,"tags":["埃斯特","百泉台","水风琴","龙泉","台地","利戈里奥"],"lead":"四层台地、上百眼泉——意大利人终于把「水」从灌溉工具变成了乐器。","pts":[{"h":"基本形制","b":"埃斯特庄园位于蒂沃利，利戈里奥设计，是文艺复兴中期台地园的代表作。四层台地沿山坡叠起，中轴贯通，水景与雕塑、植坛交织，被称为「水之园」。"},{"h":"水景体系","b":"百泉台：一条长达百余米的挡土墙上排列上百个喷泉出口，形成连续水幕；水风琴：利用水流压缩空气发声，伴有机械控制的活动小雕像；龙泉：巨型瀑布沿山坡跌落；椭圆形喷泉：位于底层，是视觉焦点。"},{"h":"布局手法","b":"中轴贯穿各台层，但并非一条直线上到底，而是随地形转折、以台阶与坡道衔接；每层台地有独立的几何植坛与丛林，台层之间以挡土墙与栏杆分隔；建筑（府邸）位于高处，控制全园。"},{"h":"与法国古典主义的区别","b":"意大利台地园重「台层之间的变化与惊喜」——每上一层看到不同景象；法国古典主义重「一条轴线看到底」的透视纵深。这是两种不同的空间策略。"}],"q":[{"k":"名词","t":"埃斯特庄园","a":"意大利文艺复兴中期台地园的代表作，位于蒂沃利，由利戈里奥设计。庄园沿山坡辟为四层台地，中轴贯通而以台阶、坡道随地形转折衔接；水景极为丰富，有长达百余米、排列上百个喷泉出口的「百泉台」，利用水流压缩空气发声的「水风琴」，以及巨型「龙泉」瀑布与椭圆形喷泉；水景与雕塑、几何植坛交织，故被称为「水之园」。它体现了意大利台地园「台层之间变化与惊喜」的空间策略，与法国古典主义「一轴到底」的透视形成对照。","kp":"位置与设计者（2分）＋水景体系（2分）＋空间特征（1分）","err":"不要只写「有很多喷泉」。要点出「百泉台、水风琴、龙泉」这三处具体水景，以及「四层台地」的形制。"},{"k":"论述","t":"比较意大利台地园与法国古典主义园林的空间策略","a":"一、地形前提不同。意大利多丘陵，台地园依山分层，高差是设计的主角；法国多为平原与缓坡，凡尔赛的场地本身平淡，靠人工开凿运河、堆筑山丘来制造起伏。二、轴线处理不同。意大利的中轴随地形转折，以台阶、坡道、挡土墙衔接，每上一层看到不同景象，强调「台层之间的变化与惊喜」；法国古典主义则追求「一条轴线看到底」的透视纵深，凡尔赛的东西主轴贯穿宫殿、花园直至大运河，消失于天际。三、水景用法不同。意大利用水造「惊奇」——百泉台的水幕、水风琴的声音、龙泉的跌落，是近身的、可听可感的；法国用水造「无限」——大运河是反射天空与轴线的镜面，是远观的、几何的。四、植物处理不同。意大利用丛林剧场、绿篱围合小空间，植物是建筑的材料；法国用修剪成型的绿色织锦、刺绣花坛，植物是图案的颜料。五、共同点与分野。两者都追求几何秩序与人工控制自然，但意大利是「在自然地形上做文章」，法国是「把自然改造成几何」。这一分野直接影响了18世纪英国风景园对二者的共同反叛。","kp":"地形前提（3分）＋轴线（4分）＋水景（3分）＋植物（2分）＋共同点（2分）","err":"不要写成「意大利台地、法国轴线」这种一句话对比。要落到「为什么」——地形差异导致的空间策略差异。"},{"k":"绘图","t":"绘出埃斯特庄园平面示意，并标注四层台地与主要水景","a":"绘图要点：①外轮廓为纵向长方形，依山坡自下而上分四层；②中轴贯穿全园；③底层画椭圆形喷泉与几何植坛；④第二层画百泉台（长条形，排列喷泉出口）；⑤第三层画水风琴（建筑符号）与丛林；⑥顶层画府邸建筑与龙泉瀑布；⑦标注：椭圆形喷泉、百泉台、水风琴、龙泉、四层台地。","kp":"四层台地（4分）＋中轴（2分）＋三处水景（3分）＋标注（1分）","err":"百泉台是一条长墙上的连续喷泉，不是单个喷泉；水风琴是建筑，不是水池。"}],"img":"este"},{"id":"w12","seq":20,"day":3,"t":"法国文艺复兴：城堡与花园","era":"w6","y":1550,"place":"卢瓦尔河谷","lat":47.4,"lon":0.7,"tags":["法国文艺复兴","谢农索","枫丹白露","维兰德里","模纹花坛"],"lead":"法国人先在卢瓦尔河谷的城堡旁种花园，然后把意大利的台地拆平，换成了平面上的轴线。","pts":[{"h":"谢农索庄园","b":"跨河而建的城堡庄园，花园位于城堡两侧的台地上，以「狄安娜花坛」著称。花园以模纹花坛为主，平面几何图案，四周以水渠围合。"},{"h":"枫丹白露宫苑","b":"弗朗索瓦一世改建的中世纪猎庄，意大利艺术家参与装饰。园林以矩形水池与花坛为主，是法国文艺复兴园林的代表。"},{"h":"维兰德里庄园","b":"三层台地的文艺复兴园林，以「爱情花园」著称：四个方形花坛分别象征「温情之爱」「炽热之爱」「轻薄之爱」「悲情之爱」，以不同植物与造型表达。"},{"h":"法国文艺复兴特征","b":"①仍受意大利影响，保留台地与台阶；②但地形平坦，台地高度降低，轴线在平面上展开；③模纹花坛（parterre）成为主角，几何图案以黄杨修剪、彩色碎石衬底；④水景以矩形水池、水渠为主，不再是意大利式的跌水。"}],"q":[{"k":"名词","t":"模纹花坛","a":"法国文艺复兴时期盛行的花坛形式，以黄杨修剪成涡卷、几何纹样，底衬彩色碎石、碎砖或土壤，形成如刺绣般的图案，故又称刺绣花坛。它多在平面展开，不强调高度，与建筑的轴线相配合，是法国规则式园林最具辨识度的要素之一。模纹花坛把意大利台地园的立体植坛转化为平面图案，标志着法国园林从「台地」转向「平面轴线」。","kp":"形制（2分）＋材料与工艺（2分）＋意义（1分）","err":"不要与「结园」混。结园是中世纪绿篱图案花坛，模纹花坛是法国文艺复兴的刺绣纹样花坛，后者更精细、更平面化。"},{"k":"简答","t":"简述法国文艺复兴园林的特点","a":"①仍受意大利影响，保留台地与台阶，但地形平坦，台地高度降低；②轴线在平面上展开，不再依赖山坡高差；③模纹花坛成为主角，黄杨修剪成涡卷纹样，彩色碎石衬底；④水景以矩形水池、水渠为主，少见意大利式跌水；⑤建筑与花园关系更紧密，城堡常跨河而建（如谢农索）；⑥代表作品：谢农索庄园、枫丹白露宫苑、维兰德里庄园。总体是从意大利台地园向法国古典主义平面轴线过渡的中间形态。","kp":"台地变化（2分）＋轴线（2分）＋花坛（2分）＋水景（2分）＋代表（2分）","err":"容易把法国文艺复兴与法国古典主义混为一谈。前者仍有台地、仍受意大利影响，后者才是中轴一统、透视无限。"}]},{"id":"w10","seq":21,"day":3,"t":"兰特庄园：台地园的教科书","era":"w5","y":1560,"place":"巴尼亚亚","lat":42.42,"lon":12.13,"tags":["兰特","维尼奥拉","链式瀑布","四层台地","中轴"],"lead":"四层台地、一条链式瀑布从中轴贯下——兰特把台地园的全部规则压缩进一个可以读完的样本。","pts":[{"h":"基本形制","b":"兰特庄园位于巴尼亚亚，维尼奥拉设计，是文艺复兴中期最完整的台地园。四层台地以链式瀑布串联，中轴贯穿，几何植坛与丛林对比，被称为「台地园教科书」。"},{"h":"四层台地的内容","b":"第一层：平坦的植坛区，几何花坛与水池；第二层：链式瀑布（catena d'acqua）沿中轴跌落，两侧对称布置；第三层：丛林区与喷泉；第四层：源泉（Fontana dell'Organo）与观景平台。"},{"h":"链式瀑布的意义","b":"水沿中轴的石槽层层跌落，既是视觉焦点，也是听觉装置，同时把四层台地在「动」上连成一体——这是意大利台地园处理高差与水景的经典手法。"},{"h":"中轴与对称","b":"全园以一条中轴贯穿，各层台地对称布置，但每层的内容不同（植坛、瀑布、丛林、源泉），形成「统一中的变化」。"}],"q":[{"k":"名词","t":"兰特庄园","a":"意大利文艺复兴中期最完整的台地园，位于巴尼亚亚，由维尼奥拉设计。庄园辟为四层台地，以一条中轴贯穿，各层对称布置而内容各异：第一层为几何植坛与水池，第二层为沿中轴跌落的链式瀑布，第三层为丛林与喷泉，第四层为源泉与观景平台。链式瀑布既是视觉焦点又是听觉装置，把四层台地在动势上连成一体。全园结构清晰、规则完备，被称为「台地园教科书」，是理解意大利台地园形制的最佳样本。","kp":"位置与设计者（2分）＋四层内容（2分）＋链式瀑布（1分）","err":"四层台地的内容要能按顺序说出来，这是画图题和简答题的共同要求。"},{"k":"绘图","t":"绘出兰特庄园的平面示意，并标注四层台地与中轴","a":"绘图要点：①外轮廓为纵向长方形，依山坡自下而上分为四层，各层进深大致相当；②一条中轴自上而下贯穿全园，位于图面中央；③第一层（最下）：画几何植坛（方格或对称图案）与圆形水池；④第二层：中轴上画链式瀑布（用连续的水槽或跌水符号表示），两侧对称画植坛；⑤第三层：画丛林（用树冠符号表示）与喷泉；⑥第四层（最上）：画源泉建筑与观景平台，末端为端点；⑦标注：中轴、四层台地、链式瀑布、源泉。","kp":"四层台地位置正确（4分）＋中轴贯穿（3分）＋链式瀑布（3分）＋要素标注（2分）","err":"常见错误是把四层画成等宽——实际各层进深不同，越往上越窄；中轴必须是一条直线贯穿到底，不能错位。"},{"k":"绘图","t":"绘出兰特庄园平面示意，并标注四层台地与链式瀑布","a":"绘图要点：①外轮廓为纵向长方形，自下而上分四层；②中轴贯穿；③第一层画几何植坛与圆形水池；④第二层中轴上画链式瀑布（连续水槽），两侧对称植坛；⑤第三层画丛林与喷泉；⑥第四层画源泉建筑与观景平台；⑦标注：四层台地、链式瀑布、源泉、中轴。","kp":"四层顺序（4分）＋链式瀑布位置（3分）＋中轴（2分）＋标注（1分）","err":"链式瀑布在第二层、沿中轴，这是兰特最标志性的要素，位置不能错。"}],"img":"lant"},{"id":"w11","seq":22,"day":3,"t":"巴洛克：法尔奈斯与伊索拉贝拉","era":"w5","y":1580,"place":"卡普拉罗拉","lat":42.35,"lon":12.13,"tags":["法尔奈斯","维尼奥拉","巴洛克","螺旋阶梯","水剧场","伊索拉贝拉"],"lead":"巴洛克把台地园推向戏剧化——螺旋阶梯、水剧场、巨大的雕像，一切都在制造惊奇。","pts":[{"h":"法尔奈斯庄园","b":"位于卡普拉罗拉，维尼奥拉设计。五角形别墅与台地园结合，螺旋阶梯、海豚喷泉、秘密花园，空间层次丰富。巴洛克时期的改造加强了戏剧性。"},{"h":"巴洛克特征","b":"①强调动势与变化，轴线不再单一，出现斜轴、交叉轴；②水景戏剧化，出现水剧场、惊奇喷泉（突然喷水惊吓宾客）；③装饰繁复，雕像、马赛克、卵石镶嵌大量使用；④空间层次增多，出现秘密花园、丛林剧场等「园中园」。"},{"h":"伊索拉贝拉庄园","b":"位于马焦雷湖的岛屿上，是意大利台地园中唯一的岛屿庄园。台地层层叠起如金字塔，顶端为花园，被称为「湖上的台地园」。"},{"h":"加尔佐尼庄园","b":"巴洛克晚期代表。三层台阶处在纵横轴线交汇点，起主导作用；大台阶并非引向别墅，而是沿中轴布置带状跌水瀑布，顶端为象征罗马城的法玛神像与半圆形水池。受法式园林影响，花坛不再强调严格对称，更注重色彩形态对比与芬芳气息。"}],"q":[{"k":"名词","t":"巴洛克园林","a":"17世纪意大利文艺复兴后期的园林风格。特征：①强调动势与变化，轴线不再单一，出现斜轴与交叉轴；②水景戏剧化，出现水剧场、惊奇喷泉（突然喷水惊吓宾客）；③装饰繁复，雕像、马赛克、卵石镶嵌大量使用；④空间层次增多，出现秘密花园、丛林剧场等「园中园」；⑤台阶与挡土墙的体量加大，常作纪念碑式处理。代表作品有法尔奈斯庄园、伊索拉贝拉庄园、加尔佐尼庄园。它把台地园从「秩序」推向「戏剧」，为法国古典主义提供了夸张的语汇。","kp":"动势与轴线（2分）＋水景戏剧化（2分）＋装饰与层次（1分）","err":"不要与「意大利文艺复兴园林」笼统混答。巴洛克的标志是「戏剧化」——水剧场、惊奇喷泉、斜轴。"},{"k":"简答","t":"简述加尔佐尼庄园的造园特点","a":"①三层台阶处在花园纵横轴线的交汇点，在整体构图中起主导作用；②大台阶并非将人引向别墅建筑，而是沿花园中轴布置带状跌水瀑布，中轴顶端是象征罗马城的法玛神像与半圆形水池；③台阶挡墙以马赛克形成色彩丰富的花丛图案，壁龛中点缀红色陶土人像；④入口外放置花神弗洛尔与吹奏芦笛的潘神雕像迎接游人；⑤受法式园林影响，模纹花坛不再强调严格对称，更注重植物装饰的色彩形态对比与芬芳气息；⑥园中处处装饰卵石镶嵌图案与黄杨造型动物，气氛轻松活跃。","kp":"轴线与台阶（2分）＋跌水中轴（2分）＋装饰手法（3分）＋法式影响（3分）","err":"加尔佐尼的特别之处是「大台阶不引向别墅而引向跌水」，这个反常规处理是必答点。"}]},{"id":"c12","seq":23,"day":3,"t":"江南私家园林的成熟","era":"c5","y":1600,"place":"苏州","lat":31.3,"lon":120.62,"tags":["江南园林","拙政园","留园","艺圃","扬州","盐商"],"lead":"苏州的文人、扬州的盐商，用两种财力把江南变成了中国园林最密集的地方。","pts":[{"h":"江南园林的兴盛","b":"苏州、扬州、杭州为盛。规模小、小中见大，叠山理水与建筑花木综合造景，追求「虽由人作，宛自天开」。"},{"h":"苏州园林","b":"以文人园为主，拙政园（明正德，王献臣建，文徵明参与擘画）、留园（明徐泰时东园，清刘恕改建）、艺圃（明文震孟）、网师园（清宋宗元）为代表。特点是疏朗雅致、以水为中心、建筑精巧。"},{"h":"扬州园林","b":"以盐商宅园为主，个园（黄至筠，四季假山）、何园（寄啸山庄）、小盘谷为代表。特点是叠山奇巧、装饰繁丽、湖上园林（瘦西湖）发达。"},{"h":"岭南园林","b":"余荫山房、可园、清晖园、梁园，以「藏而不露、缩龙成寸」见长，装饰繁丽而空间精巧。"},{"h":"私家园林综述","b":"明清私家园林的共同特征：①规模小，小中见大；②以水为中心组织空间；③叠山理水与建筑花木综合造景；④诗画入园，题名点景；⑤园主多为文人或富商，园是身份与品味的象征。"}],"q":[{"k":"论述","t":"比较苏州园林与扬州园林的异同","a":"一、相同处。①同属江南私家园林，规模不大、小中见大；②都以水为中心组织空间；③都讲究叠山理水、建筑花木综合造景；④都追求「虽由人作，宛自天开」。二、园主与气质不同。苏州园林的园主多为文人、退官（王献臣、文震孟、宋宗元），气质疏朗雅致、书卷气重，建筑精巧而不繁复；扬州园林的园主多为盐商（黄至筠、何芷舠），财力雄厚，气质奇巧繁丽，叠山追求奇特（个园四季假山），装饰更华丽。三、空间手法不同。苏州园林多为宅园合一的高墙深院，空间内向、层层递进；扬州园林多与城市水系结合，瘦西湖一线串起个园、何园、小盘谷，形成「湖上园林」的开放格局。四、叠山风格不同。苏州以太湖石为主，追求瘦透漏皱、婉转多姿（环秀山庄、留园冠云峰）；扬州黄石与太湖石并用，追求奇峰异壑、气势雄健（个园秋山）。结论：苏州是「文人之园」，扬州是「商人之园」，两者共同构成江南园林的两极。","kp":"相同（4分）＋园主气质（4分）＋空间（3分）＋叠山（3分）","err":"不要笼统写「江南园林」。苏州与扬州的差别，本质是「文人财力」与「盐商财力」的差别，这个判断是得分核心。"},{"k":"名词","t":"个园","a":"清代扬州盐商黄至筠的宅园，以四季假山著称。春山用笋石（石笋）插于竹林，象征春笋破土；夏山用太湖石，配水池与浓荫，清凉宜人；秋山用黄石，峰峦雄健、蹬道盘旋，是全园高潮；冬山用宣石（雪石），色白如雪，配风音洞制造北风呼啸之声。一园之内遍历四时，以「分峰用石」的手法把时间维度引入空间，是扬州园林叠山艺术的代表，也是中国古典园林中「以石写时」的孤例。","kp":"园主与位置（1分）＋四季假山（3分）＋手法意义（1分）","err":"四季假山的石种对应关系要能说清：春笋石、夏太湖石、秋黄石、冬宣石。这是名词解释的核心。"},{"k":"绘图","t":"绘出拙政园中部平面示意，并标注主要景点","a":"绘图要点：①外轮廓略呈长方形；②中部以水池为中心，水面占三分之一，池中垒土石构东西两山；③池南画远香堂（主体建筑），池北画见山楼，池西画香洲、小飞虹（廊桥）；④池东画梧竹幽居、绣绮亭；⑤池中两山之间架小桥，山上植落叶树间以常绿树；⑥标注：水池、远香堂、见山楼、香洲、小飞虹、梧竹幽居。","kp":"以水为中心（4分）＋池中两山（3分）＋主要建筑（2分）＋标注（1分）","err":"拙政园的关键是「以水为中心、水面占三分之一」，池中两山是它的特色。"}],"img":"zhuozhengyuan"},{"id":"c18","seq":24,"day":3,"t":"寺观园林：宗教的山水","era":"c5","y":1600,"place":"中国","lat":30.0,"lon":120.0,"tags":["寺观园林","佛寺","道观","名山","潭柘寺","灵隐寺"],"lead":"名山被寺庙占据，寺庙又反过来塑造了名山——中国的山水风景有一半是宗教造的。","pts":[{"h":"寺观园林的三种形态","b":"①名山寺观：依托名山大川，如五台山、峨眉山、普陀山、九华山；②城市寺观：位于城内或近郊，如北京法源寺、白云观；③乡村寺观：散布乡野，规模较小。"},{"h":"名山寺观的特点","b":"①选址：占据名山胜景，以自然山水为骨架；②布局：沿山路展开，殿堂、塔、池、花木依山就势；③氛围：以宗教氛围为主，兼有游览功能；④植物：多古树名木（松、柏、银杏），与宗教象征结合。"},{"h":"寺观园林的实例","b":"北京潭柘寺（「先有潭柘寺，后有北京城」）、法源寺、白云观；杭州灵隐寺；苏州寒山寺；四川青城山古常道观；乐山乌尤寺。"},{"h":"寺观园林的公共性","b":"寺观园林向公众开放，是古代中国最重要的公共游憩空间之一。庙会、进香、游览三者结合，形成独特的公共文化。"}],"q":[{"k":"简答","t":"简述中国寺观园林的类型与特点","a":"类型有三：①名山寺观——依托五台山、峨眉山、普陀山、九华山等名山大川；②城市寺观——位于城内或近郊，如北京法源寺、白云观；③乡村寺观——散布乡野，规模较小。特点：①选址——占据名山胜景，以自然山水为骨架；②布局——沿山路展开，殿堂、塔、池、花木依山就势；③氛围——以宗教氛围为主，兼有游览功能；④植物——多古树名木（松、柏、银杏），与宗教象征结合；⑤公共性——向公众开放，是古代重要的公共游憩空间，庙会、进香、游览三者结合。","kp":"三类型（3分）＋特点五项（5分）＋公共性（2分）","err":"寺观园林的核心是「宗教＋公共」双重属性，这是它区别于皇家、私家园林的关键。"}]},{"id":"c11","seq":25,"day":4,"t":"计成与《园冶》：造园有了理论","era":"c5","y":1631,"place":"仪征","lat":32.28,"lon":119.18,"tags":["计成","园冶","兴造论","相地","立基","掇山","借景","因借体宜"],"lead":"一个会画画的匠人，把造园的经验写成了书——中国园林从此有了自己的理论。","pts":[{"h":"计成与《园冶》","b":"计成（1582—？），字无否，江苏吴江人，能诗善画。崇祯四年（1631）成书《园冶》，是中国最早的造园专著，共三卷。"},{"h":"全书结构","b":"兴造论、园说、相地、立基、屋宇、装折、门窗、墙垣、铺地、掇山、选石、借景，共十二篇。"},{"h":"核心命题","b":"①「虽由人作，宛自天开」——造园的最高标准；②「巧于因借，精在体宜」——因借与体宜是方法；③「三分匠、七分主人」——主人（能主之人）决定园林品格；④相地六类：山林地、城市地、村庄地、郊野地、傍宅地、江湖地。"},{"h":"相地六类","b":"山林地「有高有凹，有曲有深」；城市地「闹处寻幽」；村庄地「便于栽植」；郊野地「依乎平冈曲坞」；傍宅地「可作游息」；江湖地「寻闲是福」。"},{"h":"《园冶》的地位","b":"中国第一部系统的造园理论著作，与《长物志》《闲情偶寄》共同构成明清造园理论体系。苏科大论述题八年八考古文，全部出自此书。"}],"q":[{"k":"名词","t":"《园冶》","a":"明代计成所著的中国最早的造园专著，崇祯四年（1631）成书，共三卷十二篇：兴造论、园说、相地、立基、屋宇、装折、门窗、墙垣、铺地、掇山、选石、借景。核心命题有：「虽由人作，宛自天开」的造园标准；「巧于因借，精在体宜」的方法论；「三分匠、七分主人」的主匠关系；相地六类（山林地、城市地、村庄地、郊野地、傍宅地、江湖地）。它是中国第一部系统的造园理论著作，与《长物志》《闲情偶寄》共同构成明清造园理论体系。","kp":"作者与体例（2分）＋核心命题（2分）＋地位（1分）","err":"「虽由人作，宛自天开」与「巧于因借，精在体宜」两句必须能默写，这是《园冶》的题眼。"},{"k":"名词","t":"相地","a":"造园前对基址的勘察、选择与评价，明代计成《园冶》将其列为第一篇。内容包括相看地形、地势、水源、植被、朝向和周边环境，判断可否成园、如何成园，核心是「相地合宜，构园得体」。《园冶》分山林地、城市地、村庄地、郊野地、傍宅地、江湖地六类，各有造园要点，如山林地「有高有凹，有曲有深」，城市地「闹处寻幽」。它是中国古代最早的「场地分析与选址」理论，与现代设计「现场踏勘—场地分析—总体布局」的程序相通。","kp":"定义与出处（2分）＋六类（2分）＋意义（1分）","err":"不要把「相地」写成「测量」或「平整土地」。六类要能背出四类以上，山林地与江湖地最常被追问。"},{"k":"论述","t":"试论《园冶》「虽由人作，宛自天开」的造园思想","a":"一、命题的内涵。「虽由人作」承认园林是人工创造，「宛自天开」要求人工的痕迹不能显露，最终效果要像自然生成的一样。这不是「不要人工」，而是「人工到极致而不见人工」——即「巧夺天工」。二、实现的路径。①相地：因基地之势，山林地「有高有凹，有曲有深」，不强改地形；②立基：先定厅堂，再布置亭榭，顺应山水骨架；③掇山：以假山代真山，「以土带石、先土后石」，追求山野之趣；④理水：曲折有致，做港汊水口以显源流；⑤借景：「巧于因借，精在体宜」，把园外之景纳入园内。三、思想根源。这一命题源于中国传统「天人合一」的宇宙观——人不是自然的征服者，而是自然的参与者。与法国古典主义「强迫自然接受匀称的法则」形成根本对立。四、历史影响。这一命题成为中国园林的最高标准，后世造园家无不以此为圭臬；它也解释了为什么中国园林能在小空间里营造出「咫尺山林」的效果——因为它追求的不是规模，而是「天成之趣」。结论：「虽由人作，宛自天开」不是技术标准，而是哲学命题——它把造园从「工程」提升为「艺术」。","kp":"内涵（3分）＋路径五项（6分）＋思想根源（3分）＋影响（3分）","err":"不要把「宛自天开」理解成「完全不要人工」。核心是「人工到极致而不见人工」，这个辩证关系是得分点。"}]},{"id":"w14","seq":26,"day":4,"t":"沃勒维贡特：凡尔赛的预演","era":"w6","y":1657,"place":"默伦","lat":48.53,"lon":2.66,"tags":["沃勒维贡特","富凯","勒诺特尔","三段式","洞窟喷泉"],"lead":"财政大臣富凯造了一座太漂亮的园子，结果把自己送进了监狱——但凡尔赛照抄了它。","pts":[{"h":"基本形制","b":"勒·诺特尔为财政大臣富凯所建，是凡尔赛的原型。三段式布局：前院、花园、大运河；中轴透视、刺绣花坛、洞窟喷泉。"},{"h":"三段式","b":"①前院：建筑前的铺装庭院，接待与停车；②花园：主体部分，刺绣花坛、丛林、喷泉；③大运河：轴线尽端的延长，制造无限透视。这三段后来成为法国古典主义园林的标准结构。"},{"h":"洞窟喷泉","b":"园中的洞窟（grotto）内设喷泉与雕像，水从洞窟中涌出，是巴洛克趣味与古典主义秩序的结合点。"},{"h":"历史逸事","b":"富凯炫耀此园，触怒路易十四，被捕入狱；路易十四随后命勒·诺特尔建造凡尔赛，规模远超沃勒维贡特。这段故事说明园林在17世纪法国是政治表态。"}],"q":[{"k":"名词","t":"沃勒维贡特庄园","a":"17世纪法国财政大臣富凯的府邸庄园，由勒·诺特尔设计，是凡尔赛宫苑的原型。庄园采用三段式布局：前院、花园、大运河，中轴透视贯穿全园，配刺绣花坛与洞窟喷泉。它第一次完整确立了法国古典主义园林的空间结构，后因过于奢华触怒路易十四，富凯被捕，路易十四随即命勒·诺特尔建造规模更大的凡尔赛。它是理解法国古典主义园林形成过程的关键作品。","kp":"位置与设计者（2分）＋三段式（2分）＋历史意义（1分）","err":"不要与凡尔赛混。沃勒维贡特是「原型」，凡尔赛是「巅峰」，两者的关系要能说清。"},{"k":"简答","t":"简述法国古典主义园林的三段式布局","a":"①前院：建筑前的铺装庭院，用于接待、停车与仪仗，是建筑与花园之间的过渡；②花园：主体部分，以刺绣花坛、丛林、喷泉、水池构成，中轴贯穿，几何构图严谨；③大运河：轴线尽端的延伸，以水面反射天空与轴线，制造无限透视，使园林向地平线敞开。三段式由沃勒维贡特庄园首次完整确立，成为凡尔赛及欧洲各国宫廷园林的标准结构。它把「建筑—花园—无限」组织成连续的视觉序列，是法国古典主义空间观念的物质化。","kp":"三段内容各2分（6分）＋空间逻辑（2分）＋影响（2分）","err":"三段式不是简单的「前中后」。核心是「建筑—花园—无限」的视觉递进，大运河的作用是制造无限。"}],"img":"vaux"},{"id":"w15","seq":27,"day":4,"t":"英国规则式：先学法国","era":"w7","y":1660,"place":"伦敦","lat":51.48,"lon":-0.3,"tags":["英国规则式","汉普顿宫","威廉三世","绿篱","迷宫"],"lead":"在变成「自然风景园」之前，英国人也曾认真地模仿法国——汉普顿宫就是证据。","pts":[{"h":"汉普顿宫苑","b":"威廉三世时期按法国风格改造，勒诺特尔的弟子参与设计。以几何花坛、运河、绿篱迷宫著称，是英国规则式园林的代表。"},{"h":"英国规则式特征","b":"①受法国与荷兰双重影响，几何构图严谨；②运河笔直，与法国大运河相似；③绿篱修剪精细，迷宫（maze）流行；④花坛以模纹为主；⑤整体规模小于凡尔赛，但要素齐备。"},{"h":"转折的伏笔","b":"英国多雨、多丘陵，气候与地形本不适合法国式大轴线；加之英国人崇尚自然与自由，规则式在英国始终是「外来样式」。这为18世纪自然风景园的反叛埋下伏笔。"}],"q":[{"k":"名词","t":"汉普顿宫苑","a":"英国规则式园林的代表，位于伦敦近郊。威廉三世时期按法国风格改造，勒诺特尔的弟子参与设计。园中有几何花坛、笔直运河、精细修剪的绿篱与迷宫，要素与法国古典主义园林相近，但规模较小。它说明英国在转向自然风景园之前，曾认真模仿法国规则式；而英国多雨多丘陵的自然条件与崇尚自由的文化传统，使规则式始终是外来样式，最终被18世纪的自然风景园取代。","kp":"位置与风格（2分）＋要素（2分）＋历史意义（1分）","err":"不要跳过这一段。英国园林的演进是「先规则、后自然」，缺了规则式这一环，就说不清风景园「反叛」的是什么。"},{"k":"简答","t":"简述英国规则式园林的特点与衰落原因","a":"特点：①受法国与荷兰双重影响，几何构图严谨；②运河笔直，类似法国大运河；③绿篱修剪精细，迷宫流行；④花坛以模纹为主；⑤规模小于凡尔赛但要素齐备，代表为汉普顿宫苑。衰落原因：①自然条件不适——英国多雨多丘陵，难以维持法国式大轴线与精细花坛；②文化传统不合——英国人崇尚自然与自由，规则式被视为外来样式；③思想转向——18世纪如画美学与浪漫主义兴起，反对几何对自然的压制；④经济因素——大轴线维护成本高。于是被自然风景园取代。","kp":"特点四项（5分）＋衰落原因四项（5分）","err":"衰落原因要答「自然条件＋文化传统＋思想转向」三条，只答「不好看」拿不到分。"}]},{"id":"w13","seq":28,"day":4,"t":"勒诺特尔与凡尔赛","era":"w6","y":1661,"place":"凡尔赛","lat":48.8,"lon":2.12,"tags":["勒诺特尔","凡尔赛","古典主义","大运河","刺绣花坛","中轴"],"lead":"把一条轴线从宫殿一直拉到地平线——法国人用几何学接管了整个自然。","pts":[{"h":"凡尔赛宫苑","b":"勒·诺特尔设计，法国古典主义园林的巅峰。东西主轴贯穿宫殿、花园、大运河，消失于天际；拉托娜泉池、阿波罗泉池、柑橘园、大小特里亚农宫。面积约100公顷（花园本体），连同大运河与林地更大。"},{"h":"古典主义的三大特征","b":"①中轴对称、几何构图，强调秩序、比例、统一；②主张「强迫自然接受匀称的法则」；③要素：宫殿与花园贯穿同一轴线、刺绣花坛、林荫道、喷泉与水池、修剪成型的绿色织锦、剧场式绿篱。"},{"h":"勒诺特尔的贡献","b":"①把意大利台地园的「台层变化」改造为「平面轴线纵深」；②用大运河制造无限透视——水面反射天空，轴线消失于地平线；③把园林纳入城市轴线（凡尔赛的巴黎大道），园林成为城市设计的一部分。"},{"h":"历史地位","b":"法国古典主义园林风靡全欧，成为规则式园林的最高峰，与英国自然风景园形成两大对立传统。凡尔赛是欧洲各国宫廷园林竞相模仿的典范。"}],"q":[{"k":"名词","t":"法国古典主义园林","a":"17世纪法国在唯理主义哲学与专制王权背景下形成、以勒·诺特尔为代表的规则式园林。特征：中轴对称、几何构图，强调秩序、比例、统一，主张「强迫自然接受匀称的法则」；要素包括宫殿与花园贯穿同一轴线、刺绣花坛、林荫道、喷泉与水池、修剪成型的绿色织锦、剧场式绿篱；代表作品有凡尔赛宫苑、沃勒维贡特庄园、枫丹白露。它风靡全欧，是规则式园林的最高峰，与英国自然风景园形成两大对立传统。","kp":"定义与代表（2分）＋特征与要素（2分）＋影响（1分）","err":"不要与意大利台地园混。意大利重台地跌水，法国重轴线透视；代表人物是勒·诺特尔，不是阿尔伯蒂。"},{"k":"论述","t":"试论凡尔赛宫苑如何体现法国古典主义的造园思想","a":"一、思想基础。17世纪法国唯理主义哲学强调理性与秩序，专制王权需要以空间秩序象征政治秩序，于是「强迫自然接受匀称的法则」成为造园纲领。二、轴线与透视。凡尔赛的东西主轴贯穿宫殿、花园直至大运河，消失于天际——这不是一条园内的路，而是一条「权力的视线」。它把建筑、花园、水面、天空组织成一个连续的透视序列，观者站在宫殿前就能「拥有」整片风景。三、水景的用法。大运河不是用来近身嬉水的，而是作为反射天空与轴线的镜面，制造无限延伸的错觉；拉托娜、阿波罗泉池则以神话叙事强化王权象征（阿波罗即路易十四的太阳神化身）。四、植物与地形。刺绣花坛把地面变成图案，修剪成型的绿色织锦与剧场式绿篱把树林变成建筑；平坦的场地被人工改造成几何起伏，自然完全服从几何。五、政治意义。凡尔赛不仅是园林，更是宫廷政治的舞台——轴线尽头的国王寝宫是全园的视觉焦点，贵族被安置在视线可及的范围内。结论：凡尔赛是「几何学＋政治学」的双重作品，它把园林从艺术品变成了权力的空间宣言。","kp":"思想基础（3分）＋轴线透视（4分）＋水景（3分）＋植物地形（3分）＋政治意义（3分）","err":"不要只描述「很对称很大」。核心论点是「轴线即权力的视线」，把这一句立住，再拿大运河、阿波罗泉池、国王寝宫做证据。"},{"k":"绘图","t":"绘出凡尔赛宫苑平面示意，并标注主轴与主要景点","a":"绘图要点：①外轮廓为横向展开的巨大矩形；②东西主轴贯穿宫殿、花园、大运河，一直延伸至图外；③宫殿在图的东侧（近巴黎一侧），画「U」形建筑；④宫殿西侧画刺绣花坛（几何图案）；⑤主轴两侧画丛林（方格状）；⑥主轴中段画拉托娜泉池、阿波罗泉池；⑦主轴尽端画大运河（十字形水面）；⑧标注：宫殿、刺绣花坛、拉托娜泉池、阿波罗泉池、大运河、主轴。","kp":"主轴贯穿（4分）＋三段式（3分）＋两处泉池（2分）＋大运河（1分）","err":"凡尔赛的宫殿在图的东侧（靠城市），花园向西展开——方向画反是常见错误。"}],"img":"versailles"},{"id":"w20","seq":29,"day":4,"t":"欧洲其他各国：西班牙到俄罗斯","era":"w6","y":1700,"place":"马德里","lat":40.42,"lon":-3.7,"tags":["西班牙","阿尔罕布拉","荷兰","德国","俄罗斯","彼得宫"],"lead":"法国的影响像水一样漫过整个欧洲，但每个国家都往里加了自己的东西。","pts":[{"h":"西班牙","b":"①伊斯兰园林传统：阿尔罕布拉宫（桃金娘庭园、狮子庭园），以十字水渠、瓷砖、拱廊为特征，强调封闭、阴凉、水声；②文艺复兴园林：格内拉里弗园；③勒诺特尔式：阿兰胡埃斯岛的「岛花园」。"},{"h":"荷兰","b":"①地势低平、土地珍贵，园林规模小、精致；②以运河、绿篱、整形树为主；③赫特·洛宫苑是代表；④荷兰风格影响了英国规则式（威廉三世带来）。"},{"h":"德国","b":"①规则式：海伦赫森宫苑、宁芬堡宫苑、施维钦根宫苑；②风景式：沃尔利兹园（Wörlitz），是德国最早的自然风景园之一。"},{"h":"俄罗斯","b":"①彼得宫（夏宫）：彼得大帝建，仿凡尔赛，以阶梯瀑布与喷泉著称；②沙皇村（普希金城）；③巴甫洛夫风景园：仿英国自然式。"}],"q":[{"k":"名词","t":"阿尔罕布拉宫","a":"中世纪西班牙格拉纳达的摩尔人宫殿园林，是伊斯兰园林在西方最完整的遗存。以桃金娘庭园与狮子庭园为代表：庭院以十字水渠分为四块，水渠交汇处设喷泉，四周环以拱廊，墙面满铺彩色瓷砖与灰泥雕饰。特征是封闭内向、强调阴凉与水声、以几何图案装饰。它体现了伊斯兰园林「四天国」（Chahar Bagh）的宇宙观，与基督教西方的开放轴线形成鲜明对照。","kp":"位置与性质（2分）＋庭园特征（2分）＋文化意义（1分）","err":"不要与「格内拉里弗园」混。阿尔罕布拉是摩尔人宫殿，格内拉里弗是其后来的夏宫花园。"},{"k":"简答","t":"简述法国古典主义园林对欧洲各国的影响","a":"①西班牙：在伊斯兰园林传统之上引入勒诺特尔式，如阿兰胡埃斯岛的「岛花园」。②荷兰：受法国影响但因地势低平、土地珍贵而规模小、精致，以运河与绿篱为主，代表为赫特·洛宫苑；荷兰风格又反过来影响英国规则式。③德国：海伦赫森、宁芬堡、施维钦根等宫苑模仿凡尔赛的轴线与花坛；同时出现沃尔利兹园这样的早期自然风景园。④俄罗斯：彼得宫仿凡尔赛，以阶梯瀑布与喷泉著称；沙皇村与巴甫洛夫园则分别呈现规则式与风景式。共同规律：各国都先模仿法国的轴线与花坛，再结合本土地形气候与审美传统加以改造，最终在英国形成自然风景园的反叛。","kp":"四国各2分（8分）＋共同规律（2分）","err":"不要只写「都学法国」。要答出「学完之后各自改了什么」，这才是影响史的重点。"}]},{"id":"w23","seq":30,"day":4,"t":"荷兰与德国：低地与森林","era":"w6","y":1700,"place":"海牙","lat":52.08,"lon":4.3,"tags":["荷兰","赫特洛","德国","海伦赫森","宁芬堡","施维钦根","沃尔利兹"],"lead":"荷兰人在海平面以下造园，德国人在森林里造园——两种地理，两种园林。","pts":[{"h":"荷兰园林","b":"①地势低平、土地珍贵，园林规模小、精致；②以运河、绿篱、整形树为主；③赫特·洛宫苑（Het Loo）是代表，中轴贯穿，花坛与丛林对称；④荷兰风格通过威廉三世传入英国，影响汉普顿宫。"},{"h":"德国规则式","b":"海伦赫森宫苑（Herrenhausen）：勒诺特尔式，中轴、花坛、丛林剧场；宁芬堡宫苑（Nymphenburg）：以运河与浴场建筑著称；施维钦根宫苑（Schwetzingen）：融合法式与英式。"},{"h":"德国风景式","b":"沃尔利兹园（Wörlitz）：德国最早的自然风景园之一，由弗兰茨亲王建造，结合如画美学与启蒙思想，园中有古典建筑、哥特式教堂、中国桥。"},{"h":"规律","b":"荷兰因土地珍贵而「小而精」，德国因森林广布而「大而野」；两者都先学法国，再结合本土条件改造。"}],"q":[{"k":"名词","t":"赫特·洛宫苑","a":"荷兰规则式园林的代表，位于阿珀尔多伦，为威廉三世所建。因荷兰地势低平、土地珍贵，园林规模不大但极为精致：以中轴贯穿全园，两侧对称布置花坛、丛林与水池，绿篱与整形树修剪精细，并大量运用运河与水渠。它体现了荷兰园林「小而精」的特点，并通过威廉三世传入英国，影响了汉普顿宫苑的规则式改造，是法国古典主义在北欧传播的重要一环。","kp":"位置与性质（2分）＋特征（2分）＋影响（1分）","err":"荷兰园林的关键词是「小而精」——因为土地珍贵，不能像法国那样铺开大轴线。"},{"k":"简答","t":"简述法国古典主义园林在德国与俄罗斯的传播","a":"①德国：海伦赫森宫苑模仿勒诺特尔式，有中轴、花坛、丛林剧场；宁芬堡宫苑以运河与浴场建筑著称；施维钦根宫苑融合法式与英式。同时德国也出现了沃尔利兹园这样的早期自然风景园，说明德国在接受法国影响的同时保留了本土的如画趣味。②俄罗斯：彼得宫（夏宫）由彼得大帝建造，仿凡尔赛，以阶梯瀑布与喷泉著称，是俄罗斯勒诺特尔式的代表；沙皇村（普希金城）规模宏大；巴甫洛夫风景园则仿英国自然式。③共同规律：两国都先完整移植法国的轴线、花坛、喷泉体系，再结合本土的气候、地形与审美加以改造，最终在英国影响下转向风景式。","kp":"德国三例（4分）＋俄罗斯三例（4分）＋共同规律（2分）","err":"彼得宫的「阶梯瀑布」是标志性要素，与凡尔赛的大运河形成对比，答题时点出来会加分。"}]},{"id":"c15","seq":31,"day":4,"t":"避暑山庄：山地园林的极致","era":"c6","y":1703,"place":"承德","lat":40.99,"lon":117.94,"tags":["避暑山庄","外八庙","康熙","乾隆","七十二景","山区"],"lead":"一座园子里有湖、有平原、有山——康熙把整个塞外的地貌搬进了围墙。","pts":[{"h":"基本事实","b":"清康熙四十二年至乾隆五十七年（1703—1792）建成的清代皇家离宫别苑，位于河北承德，又称热河行宫、承德离宫。占地约564公顷，是我国现存最大的古典皇家园林。"},{"h":"布局","b":"「前宫后苑」，宫殿区居南，苑景区分湖区、平原区、山区三部分，集南北园林之长。"},{"h":"造景","b":"以「康乾七十二景」著称，如烟雨楼、金山亭、文园狮子林；「以山为骨、以水为脉」，风格朴素淡雅。山区占全园三分之二，峰峦涌叠，最高峰达150米。"},{"h":"外八庙","b":"清代在避暑山庄东部、北部山麓陆续修建的皇家寺庙群，康熙五十二年至乾隆四十五年（1713—1780）陆续建成，现存八座。溥仁寺、普宁寺、安远庙、普乐寺、普陀宗乘之庙（仿布达拉宫）、须弥福寿之庙（仿扎什伦布寺）等，融合汉、藏、蒙建筑风格。是「以寺庙怀柔」民族政策的产物。"},{"h":"价值","b":"与周围外八庙共同构成世界文化遗产（1994年）。"}],"q":[{"k":"名词","t":"避暑山庄","a":"清康熙四十二年至乾隆五十七年（1703—1792）建成的清代皇家离宫别苑，位于河北承德，又称热河行宫、承德离宫。占地约564公顷，是我国现存最大的古典皇家园林。布局「前宫后苑」，宫殿区居南，苑景区分湖区、平原区、山区三部分，集南北园林之长。以「康乾七十二景」著称，如烟雨楼、金山亭、文园狮子林；「以山为骨、以水为脉」，风格朴素淡雅。与周围「外八庙」共同构成世界文化遗产，是清代皇家园林与民族政策结合的代表。","kp":"时代与性质（2分）＋规模与布局（2分）＋代表景点与价值（1分）","err":"避暑山庄是「离宫」不是皇家园居主体；面积约564公顷（不是290公顷，那是颐和园）；「山庄」不等于「山上的园」，它兼有湖区与平原区。"},{"k":"名词","t":"外八庙","a":"清代在承德避暑山庄东部、北部山麓陆续修建的皇家寺庙群，因其中八座住有喇嘛、由理藩院管辖，且地处京师之外，故称「外八庙」。康熙五十二年至乾隆四十五年（1713—1780）陆续建成。实例有溥仁寺、普宁寺、安远庙、普乐寺、普陀宗乘之庙（仿布达拉宫）、须弥福寿之庙（仿扎什伦布寺）等，融合汉、藏、蒙建筑风格。它是清代「以寺庙怀柔」民族政策的产物，1994年与避暑山庄一同列入世界文化遗产。","kp":"定义与得名（2分）＋代表寺庙（2分）＋意义（1分）","err":"外八庙在承德，不在北京；「外」指京师之外，不是「外墙之外」；普陀宗乘之庙仿布达拉宫、须弥福寿之庙仿扎什伦布寺，这两组对应关系常考。"},{"k":"简答","t":"简述避暑山庄的空间布局","a":"①总体格局「前宫后苑」：宫殿区居南，苑景区居北，符合中国传统宫殿园林的前后关系。②宫殿区：正宫、松鹤斋、万壑松风、东宫四组，朴素淡雅，不施彩绘，体现「山庄」的质朴格调。③苑景区分三部：湖区——洲岛错落，仿江南水乡，有烟雨楼、金山亭；平原区——万树园、试马埭，摹拟塞外草原，设置蒙古包，用于政治活动；山区——占全园三分之二，峰峦涌叠，最高峰150米，以山为骨。④整体特色：以山为骨、以水为脉，集南北园林之长，风格朴素淡雅。","kp":"前宫后苑（2分）＋宫殿区（2分）＋三区（4分）＋整体特色（2分）","err":"「山区占三分之二」是关键数字；三区的顺序是湖区、平原区、山区，不要颠倒。"},{"k":"绘图","t":"绘出艮岳平面示意，并标注主峰与水体格局","a":"绘图要点：①外轮廓略呈不规则方形；②「左山右水」——左侧（西）画万岁山主峰，右侧（东）画水面；③万岁山以北画寿山、万松岭为辅；④山体中画瀑布、洞壑、蹬道；⑤水面上源接景龙江，形成溪涧、池沼；⑥建筑四十余处散布山间，标介亭、绛霄楼等；⑦标注：万岁山、寿山、万松岭、景龙江、介亭。","kp":"左山右水格局（4分）＋主峰位置（3分）＋水系（2分）＋标注（1分）","err":"艮岳的骨架是「左山右水」，画反了就全错。主峰万岁山在左（西），水面在右（东）。"}],"img":"bishushanzhuang"},{"id":"w17","seq":32,"day":4,"t":"斯陀园与布朗","era":"w7","y":1740,"place":"白金汉郡","lat":52.03,"lon":-1.02,"tags":["斯陀园","布朗","肯特","蛇形湖","帕拉第奥桥"],"lead":"斯陀园是自然风景园的试验场——肯特开始，布朗完成，一座园子走完了整个转折。","pts":[{"h":"斯陀园","b":"自然风景园的发源地之一。肯特、布朗先后改造，从规则式转向自然式：古希腊庙、帕拉第奥桥、蜿蜒湖面，是「如画」美学的实验场。"},{"h":"布朗的手法","b":"①蛇形湖：以蜿蜒曲折的湖岸取代直线运河；②缓坡草地：一直铺到建筑脚下，无台阶；③树团：成组种植，形成明暗层次；④消隐边界：用哈哈墙使园子与牧场连成一片；⑤点景建筑：少而精，作为视觉焦点。"},{"h":"布朗的地位","b":"第一位训练有素的职业造园家。他不追求风景式园林的象征意义，而追求广阔的风景构图，强调园林与周围自然毫无过渡地融合。"},{"h":"评价的两面","b":"布朗的园林被赞为「田园牧歌」，也被批评为「千篇一律」——因为他把所有场地都处理成同样的蛇形湖与缓坡草地，抹掉了场地的个性。这一批评直接催生了雷普顿与如画派的修正。"}],"q":[{"k":"名词","t":"布朗（Lancelot Brown）","a":"18世纪英国自然风景园最著名的造园家，被称为「万能的布朗」，是第一位训练有素的职业造园家。他不追求风景式园林的象征意义，而追求广阔的风景构图，强调园林与周围自然毫无过渡地融合。手法包括：以蜿蜒曲折的蛇形湖取代直线运河，缓坡草地一直铺到建筑脚下，成组种植树木形成明暗层次，用哈哈墙消隐园界，以少而精的古典建筑作点景。代表作品有斯陀园改造、布伦海姆宫苑。他被赞为「田园牧歌」的创造者，也被批评为「千篇一律」。","kp":"身份（2分）＋手法（2分）＋评价（1分）","err":"不要与「肯特」混。肯特是过渡期，引入点景建筑；布朗是成熟期，以蛇形湖与缓坡草地为标志。"},{"k":"简答","t":"简述布朗的造园手法及其得失","a":"手法：①以蜿蜒曲折的蛇形湖取代直线运河，自然式驳岸；②缓坡草地一直铺到建筑脚下，取消台阶与挡土墙；③树木成组种植，形成孤植树、树团、树林的渐变层次；④用哈哈墙消隐园界，使园林与周围牧场无缝融合；⑤点景建筑少而精，作为视觉焦点；⑥府邸前的道路改为弧形，不再正对大门。得：创造了前所未有的「田园牧歌」式风景，使园林与自然真正融为一体，影响全欧。失：手法程式化，把所有场地都处理成同样的蛇形湖与缓坡草地，抹掉场地个性，被批评为「千篇一律」，这也直接催生了雷普顿与如画派的修正。","kp":"手法六项（6分）＋得（2分）＋失（2分）","err":"「失」这一面常被忽略，但它是理解雷普顿为何出现的关键，答题时务必写上。"}],"img":"stowe"},{"id":"w16","seq":33,"day":5,"t":"英国自然风景园：反叛几何","era":"w7","y":1750,"place":"白金汉郡","lat":52.03,"lon":-1.02,"tags":["自然风景园","如画","布朗","肯特","蛇形湖","哈哈墙"],"lead":"英国人把法国的直线全部掰弯——因为他们相信，自然的曲线才是上帝的手笔。","pts":[{"h":"成因","b":"①思想上，经验主义与浪漫主义反对唯理主义对自然的压制，沙夫茨伯里「自然即美」；②审美上，如画（picturesque）观念流行，风景画与田园诗提供了范式；③政治上，自然式被视为「英国式自由」对「法国式专制」的对照；④经济上，大轴线与精细花坛维护成本高，牧草与羊群更划算。"},{"h":"发展三阶段","b":"①萌芽：布里奇曼取消围墙、引入「哈哈墙」（ha-ha，隐蔽的壕沟围墙），使园子与牧场连成一片；②过渡：肯特（William Kent）以「自然厌恶直线」为口号，引入古典庙宇、废墟等点景建筑；③成熟：布朗（Lancelot Brown）以蛇形湖、缓坡草地、成组树丛构成「田园牧歌」，被称为「万能的布朗」。"},{"h":"造园要素","b":"①地形：起伏的缓坡草地，无台阶、无挡土墙；②水体：蜿蜒的自然式驳岸，蛇形湖是标志；③植物：孤植树、树团、树林形成渐变层次，不采用规则式种植；④建筑：古典庙宇、废墟、帕拉第奥桥、中国塔等点景建筑，少而精；⑤边界：哈哈墙消隐园界，使园林与周围自然无缝融合。"},{"h":"与中国园林的比较","b":"①相同：都反对几何、追求自然、讲究曲折变化。②不同：英国风景园是「原原本本把大自然的构景要素经过艺术组合」，用地大、追求如画的全景；中国园林是「对自然加以典型化、抽象化」，小中见大、可游可居。③结果：英国园可看不可游，中国园可游可居。"}],"q":[{"k":"名词","t":"英国自然风景园","a":"18世纪英国兴起的、反对几何规则式的园林类型。成因包括经验主义与浪漫主义思想、如画美学、政治上的「英国式自由」以及维护成本的考量。特征：起伏的缓坡草地，无台阶与挡土墙；蜿蜒的自然式驳岸与蛇形湖；孤植树、树团、树林形成渐变层次；以古典庙宇、废墟、帕拉第奥桥、中国塔等点景建筑点缀；用哈哈墙消隐园界，使园林与周围自然无缝融合。代表为斯陀园、布伦海姆宫苑、邱园。它与法国古典主义园林形成西方两大对立传统。","kp":"成因（2分）＋要素（2分）＋意义（1分）","err":"不要只写「很自然」。必须点出「哈哈墙」「蛇形湖」「点景建筑」这三个具体手段。"},{"k":"论述","t":"比较英国自然风景园与中国古典园林的异同","a":"一、相同处。①都反对几何规则式，追求自然；②都讲究曲折变化、藏露结合；③都重视水景与植物的自然形态。二、根本差异。①造园方法：英国是「原原本本把大自然的构景要素经过艺术组合，相应于用地大小呈现在人们眼前」（周维权语），即对自然的直接模仿与再现；中国是「通过对大自然及其构景要素的典型化、抽象化」来传达自然生态的信息，即写意。②尺度与效果：英国园用地大，追求如画的全景，可看不可游；中国园小中见大、咫尺山林，可游可居。③建筑地位：英国园的建筑是点景（庙宇、废墟），少而精，与自然相对分离；中国园的建筑与山水花木融糅，是「建筑美与自然美的融糅」。④哲学基础：英国是经验主义与浪漫主义，中国是天人合一的宇宙观。三、相互影响。18世纪「中国热」中，钱伯斯在邱园建中国塔，中国园林的曲折趣味影响了英国风景园；但英国园最终走向了「如画的全景」，而非中国的「写意山水」。结论：两者都反几何，但一个是「再现自然」，一个是「表现自然」，这是中西园林最本质的分野。","kp":"相同（3分）＋方法差异（5分）＋尺度建筑（4分）＋哲学（3分）","err":"不要写成「都很自然所以一样」。核心是「再现」与「表现」的分野，这一句必须立住。"},{"k":"绘图","t":"绘出斯陀园平面示意，并标注自然风景园的要素","a":"绘图要点：①外轮廓为不规则形，无直线边界；②中部画蜿蜒的蛇形湖；③湖畔画缓坡草地，一直铺到建筑脚下；④草地上画成组树团、孤植树；⑤园中点缀古典庙宇、帕拉第奥桥；⑥边界用虚线表示哈哈墙（隐蔽壕沟）；⑦标注：蛇形湖、缓坡草地、树团、帕拉第奥桥、哈哈墙。","kp":"蛇形湖（3分）＋缓坡草地与树团（3分）＋点景建筑（2分）＋哈哈墙（2分）","err":"自然风景园的标志是「没有直线」——如果画出了直路直岸，就说明没理解。"}],"img":"kew"},{"id":"w22","seq":34,"day":5,"t":"中国园林西传与英中式","era":"w7","y":1750,"place":"欧洲","lat":50.0,"lon":-5.0,"tags":["中国热","英中式","传教士","纽霍夫","大报恩寺塔"],"lead":"欧洲人从传教士的图册里看见中国园林，然后用想象补全了剩下的部分。","pts":[{"h":"传播路径","b":"①13世纪马可·波罗；②16—17世纪传教士（利玛窦等）寄回文字报告；③17—18世纪商人带回瓷器、丝绸、园林图像；④纽霍夫《荷兰东印度公司使节访华记》中的大报恩寺琉璃塔版画，成为欧洲人心中的中国建筑原型。"},{"h":"中国热的表现","b":"①园林：邱园中国塔、孔庙，英中式园林；②建筑：中国亭、桥、假山；③装饰：瓷器、漆器、丝绸纹样；④思想：启蒙思想家借中国批判欧洲专制。"},{"h":"误读的成分","b":"①欧洲人看到的是「不规则」，没看到「意境」；②中国塔的层数被误传（纽霍夫版画少画一层）；③英中式园林常变成元素堆砌，塔与假山并置而不成章法。"},{"h":"历史意义","b":"中国热为英国自然风景园提供了「另一个文明也不按轴线造园」的合法性依据，客观上推动了欧洲园林的自然化转向。"}],"q":[{"k":"名词","t":"英中式园林","a":"18世纪欧洲出现的一种混合风格园林，法文 Jardin anglo-chinois。它以英国自然风景园为底，加入中国式的塔、亭、桥、假山、孔庙等元素，追求曲折、变化与「意外」的趣味。它是「中国热」的产物，源于传教士与商人带回的中国园林图像，但本质上是文化误读——欧洲人看到的是「不规则」，未理解背后的「意境」与「天人合一」，因此常流于元素堆砌。尽管如此，它为英国自然风景园提供了反几何的合法性依据，客观上推动了欧洲园林的自然化转向。","kp":"定义（2分）＋特征（2分）＋评价（1分）","err":"不要写成「中国园林的复制」。英中式是误读的产物，答题时要同时讲「影响」与「误读」两面。"},{"k":"简答","t":"简述中国园林对18世纪欧洲园林的影响","a":"①传播路径：马可·波罗—传教士文字报告—商人带回的图像与器物—纽霍夫版画中的大报恩寺琉璃塔。②观念影响：中国园林的曲折、藏露、借景、不规则，被英国造园家引为反对几何规则式的理论武器，为自然风景园提供了「另一个文明也如此」的合法性。③要素影响：塔、亭、桥、假山、孔庙进入欧洲园林，形成英中式园林（Jardin anglo-chinois）。④人物与作品：钱伯斯主持邱园，建中国塔（1762）与孔庙，著《论东方园林》。⑤局限：欧洲人理解的是表面形式而非意境，英中式常流于元素堆砌；中国塔层数亦被误传。总体是「误读式的影响」，但推动了欧洲园林的自然化转向。","kp":"传播（2分）＋观念（3分）＋要素（2分）＋人物（2分）＋局限（1分）","err":"「局限」这一层要写，只讲影响不讲误读，论述会显得单薄。"}]},{"id":"c13","seq":35,"day":5,"t":"明清皇家园林：三山五园","era":"c5","y":1750,"place":"北京西郊","lat":39.99,"lon":116.27,"tags":["三山五园","清漪园","圆明园","静宜园","静明园","畅春园"],"lead":"康熙到乾隆，把北京西郊的山水整个改造成了一座巨大的皇家园林群。","pts":[{"h":"三山五园的构成","b":"「三山」指万寿山、香山、玉泉山；「五园」指清漪园（颐和园）、静宜园、静明园、畅春园、圆明园。"},{"h":"形成过程","b":"康熙至乾隆年间依托西山、玉泉山的水源集中营造，形成「园外有园、园中有园」的集群。"},{"h":"特色","b":"以真山真水为骨架，借景西山，规模与艺术水平均为皇家园林之最。"},{"h":"历史命运","b":"1860年英法联军、1900年八国联军两度焚毁，仅清漪园于1888年重建后改称颐和园得以留存。"},{"h":"皇家园林的成就","b":"①规模宏大，占地与体量远超私家园林；②真山真水，借景西山；③集锦式布局，园中有园（如谐趣园仿寄畅园）；④中西合璧（圆明园西洋楼）；⑤政治功能（避暑山庄的外八庙）。"}],"q":[{"k":"名词","t":"三山五园","a":"清代北京西郊以皇家园林为主体的园林群。「三山」指万寿山、香山、玉泉山；「五园」指清漪园（颐和园）、静宜园、静明园、畅春园、圆明园。康熙至乾隆年间依托西山、玉泉山的水源集中营造，形成「园外有园、园中有园」的集群。其特色是以真山真水为骨架，借景西山，规模与艺术水平均为皇家园林之最。1860年英法联军、1900年八国联军两度焚毁，仅清漪园于1888年重建后改称颐和园得以留存。它代表了中国皇家园林的最高成就。","kp":"三山五园具体名称（3分）＋形成与特色（1分）＋历史命运（1分）","err":"五园中「静宜园」在香山、「静明园」在玉泉山，最易写错；清漪园是颐和园的前身，1860年被毁、1888年重建才改名。"},{"k":"简答","t":"简述清代皇家园林的主要成就","a":"①规模宏大：占地与体量远超私家园林，如避暑山庄约564公顷、颐和园约290公顷。②真山真水：以西山、玉泉山为骨架，借景天然山水，非人工堆叠可比。③集锦式布局：园中有园，如颐和园谐趣园仿无锡寄畅园、圆明园集天下名园之大成。④中西合璧：圆明园长春园西洋楼是中西园林合璧的孤例。⑤政治功能：避暑山庄与外八庙结合，承担怀柔蒙藏的政治使命。⑥理论与技艺集成：由皇家主持、名师设计（如样式雷），把叠山、理水、建筑、植物推向极致。","kp":"","err":""}]},{"id":"c14","seq":36,"day":5,"t":"颐和园：一池三山的集大成","era":"c6","y":1750,"place":"北京西郊","lat":39.999,"lon":116.275,"tags":["颐和园","清漪园","昆明湖","万寿山","长廊","佛香阁","西堤"],"lead":"乾隆为母亲祝寿挖的湖，最后成了中国现存最完整的皇家园林。","pts":[{"h":"基本事实","b":"清乾隆十五年（1750）建清漪园，咸丰十年（1860）毁于英法联军，光绪十二年（1886）重建，光绪十四年（1888）改名颐和园。位于北京西北郊，全园约290公顷，昆明湖水面约占四分之三。1998年列入世界文化遗产。"},{"h":"总体格局","b":"北山南水——万寿山居北，昆明湖居南，形成「背山面水」的山水骨架。"},{"h":"一池三山","b":"湖中三岛——南湖岛（龙王庙、广润灵雨祠）、治镜阁（已毁）、藻鉴堂，对应蓬莱、方丈、瀛洲。是「一池三山」造园模式的集大成者。"},{"h":"主要要素","b":"万寿山前山有南北中轴：排云门、排云殿、佛香阁（八面三层四重檐）、智慧海（无梁殿）；长廊东起邀月门、西至石丈亭，共273间；山东麓有园中园谐趣园；后山有后溪河与苏州街；东部为宫廷区；西堤六桥（界湖桥、豳风桥、玉带桥、镜桥、练桥、柳桥）；十七孔桥东连东堤、西接南湖岛。"},{"h":"造园艺术","b":"①借景西山：以园外玉泉山、西山为远景，扩大空间感；②集锦式布局：园中有园（谐趣园仿寄畅园）；③中轴与对称：佛香阁中轴与湖岸垂直；④以水为主：昆明湖占四分之三，水面开朗。"}],"q":[{"k":"绘图","t":"绘出颐和园平面示意，并标注主要景点","a":"绘图要点：①外轮廓略呈不规则四边形，西北收、东南放，左上角标指北针；②南部画大块水面（昆明湖，约占全图三分之二），一条斜线（西堤）把湖面分为西小东大两部分；③北部画万寿山，从湖岸向北画一条垂直中轴，依次点排云殿、佛香阁、智慧海；④沿山前湖岸画一条东西向长条（长廊），两端标邀月门、石丈亭；⑤湖东南画南湖岛，用十七孔桥连东堤；湖中点治镜阁、藻鉴堂；西堤上点六桥；山北画后溪河与苏州街；⑥东部画宫廷区（东宫门—仁寿殿—玉澜堂—乐寿堂）；⑦至少标注8处名称。","kp":"北山南水格局（3分）＋昆明湖西堤南湖岛十七孔桥（3分）＋万寿山中轴与长廊（2分）＋后溪河与宫廷区（2分）","err":"常见错误：把昆明湖画得比山小（湖应占大半）、忘画长廊（最有辨识度的线性要素）、中轴画成斜的（应与湖岸垂直）。"},{"k":"简答","t":"简述颐和园的造园艺术特点","a":"①北山南水的总体格局：万寿山居北、昆明湖居南，背山面水，是中国传统风水与山水审美的典范。②一池三山的继承：湖中设南湖岛、治镜阁、藻鉴堂三岛，象征蓬莱、方丈、瀛洲，是「一池三山」模式的集大成。③中轴与对称：排云门—排云殿—佛香阁—智慧海构成南北中轴，与湖岸垂直，控制全园。④长廊的线性组织：273间长廊沿山前湖岸东西展开，既是交通线，也是观景线与建筑群的纽带。⑤借景西山：以园外玉泉山、西山为远景，扩大空间感。⑥集锦式布局：园中有园，谐趣园仿无锡寄畅园，体现「移天缩地」的造园智慧。","kp":"格局（2分）＋一池三山（2分）＋中轴（2分）＋长廊（2分）＋借景与集锦（2分）","err":"颐和园的「集大成」体现在三个层面：一池三山的模式、皇家园林的规模、江南园林的移植（谐趣园），三层都要答到。"},{"k":"绘图","t":"绘出颐和园谐趣园平面示意，并标注主要建筑","a":"绘图要点：①园址在颐和园万寿山东麓，平面近方形，占地约1公顷；②园中偏南有一泓近方形水池，约占全园三分之一；③西北角引后溪河水入池，东南出园，是活水；④环池布置建筑：北面涵远堂（主体），西面瞩新楼、澄爽斋，东面饮绿、洗秋，南面知春亭、引镜；⑤以游廊环池串联各建筑，形成「以廊串景」的格局；⑥池北叠石，池南为入口；⑦标注：水池、涵远堂、瞩新楼、饮绿、洗秋、知春亭、游廊。","kp":"水池位置与形状（3分）＋环池建筑（4分）＋游廊串联（2分）＋活水出入口（1分）","err":"常见错误：把水池画成圆形（应为近方形）、忘记北面涵远堂是主体、漏掉游廊。"},{"k":"简答","t":"简述谐趣园的造园特点","a":"①园中园：位于颐和园万寿山东麓，是皇家园林中的江南风格小园，乾隆1751年仿无锡寄畅园而建，原名惠山园。②以水为中心：园中一泓近方形水池约占全园三分之一，环池布置建筑。③以廊串景：游廊环池串联涵远堂、瞩新楼、饮绿、洗秋、知春亭等，形成连续的游赏路线。④活水：西北引后溪河水入池，东南出园，水有源有流。⑤尺度亲切：占地约1公顷，建筑小巧，与颐和园的宏大规模形成对比，是「大园包小园」的典型。","kp":"园中园（2分）＋以水为中心（2分）＋游廊（2分）＋活水（2分）＋尺度（2分）","err":"谐趣园的关键是「仿寄畅园」与「园中园」，这两点必须写。"}],"img":"yiheyuan"},{"id":"w18","seq":37,"day":5,"t":"邱园与中国热","era":"w7","y":1762,"place":"伦敦","lat":51.48,"lon":-0.3,"tags":["邱园","钱伯斯","中国塔","中国热","英中式园林"],"lead":"一座中国塔立在伦敦郊外——这是西方园林第一次认真向东方学习，虽然学得不太像。","pts":[{"h":"钱伯斯与邱园","b":"钱伯斯（William Chambers，1723—1796），英国建筑师、造园家，曾到中国广州考察建筑与园林。主持邱园造景，建中国塔（1762年，高约50米）、孔庙，著《论东方园林》。主张借鉴中国园林的曲折、变化与趣味。"},{"h":"中国热的背景","b":"17—18世纪传教士与商人带回中国园林图像与文字报告，欧洲掀起「中国热」。中国的曲折、藏露、借景被英国造园家引为反对几何规则式的武器。"},{"h":"英中式园林","b":"Jardin anglo-chinois，18世纪欧洲的混合风格：以英国自然风景园为底，加入中国式的塔、亭、桥、假山等元素。它是文化误读的产物，但客观上推动了欧洲园林的自然化转向。"},{"h":"评价","b":"钱伯斯倡导的是「借鉴中国园林」而非照搬。邱园中国塔的层数曾长期被误传，第3版教材特别更正：塔的层数与江南大报恩寺琉璃塔一致，只是未将底层「副阶」计入层数。"}],"q":[{"k":"名词","t":"钱伯斯（William Chambers）","a":"18世纪英国建筑师、造园家，「中国风」的代表人物。曾到中国广州考察建筑与园林，回国后大力介绍中国园林。主持邱园造景，建中国塔（1762年，高约50米）与孔庙，著《论东方园林》，主张借鉴中国园林的曲折、变化与趣味，反对盲目模仿。他推动了「中国热」在欧洲的传播，中国塔成为中英园林交流的标志。需要说明的是，他倡导的是「借鉴」而非照搬，邱园中国塔的层数长期被误传，实与江南大报恩寺琉璃塔一致。","kp":"身份（2分）＋作品（2分）＋影响（1分）","err":"钱伯斯是英国人，不是中国人也不是法国人；代表作在邱园，不是凡尔赛。"},{"k":"论述","t":"试论18世纪「中国热」对欧洲园林的影响","a":"一、背景。17—18世纪传教士与商人带回中国的园林图像、瓷器、丝绸与文字报告，欧洲人对中国产生浓厚兴趣，形成「中国热」。二、影响的三个层面。①观念层面：中国园林的「曲折」「藏露」「借景」「不规则」被英国造园家引为反对几何规则式的理论武器——既然中国这样一个高度文明的国度都不按轴线造园，那么几何就不是唯一的美。②要素层面：塔、亭、桥、假山、孔庙等中国元素进入欧洲园林，形成「英中式园林」（Jardin anglo-chinois）。③手法层面：哈夫彭尼、钱伯斯等人尝试在自然风景园中加入「意外」「变化」「惊喜」，这与中国园林的「步移景异」有相通处。三、局限与误读。欧洲人对中国园林的理解是表面的——他们看到的是「不规则」，没看到背后的「意境」与「天人合一」；英中式园林往往变成元素的堆砌，塔与假山并置而不成章法。四、历史意义。尽管是误读，中国热客观上推动了欧洲园林从规则式向自然式的转向，为英国自然风景园提供了「另一个文明也这么做」的合法性。结论：中国热是西方园林自我变革的催化剂，而非直接的模仿对象。","kp":"背景（2分）＋三层面（7分）＋误读（3分）＋意义（3分）","err":"不要写成「中国园林影响了英国园林所以英国园林像中国」。核心是「中国作为反几何的合法性依据」，而不是形式上的照搬。"}]},{"id":"w19","seq":38,"day":5,"t":"雷普顿：在布朗与如画之间","era":"w7","y":1790,"place":"英格兰","lat":52.0,"lon":-1.3,"tags":["雷普顿","红皮书","如画","借景","三要素"],"lead":"雷普顿用一本红皮书告诉园主：改之前和改之后，差别在哪里。","pts":[{"h":"雷普顿的地位","b":"布朗与如画派之间的桥梁。他以「红皮书」（Red Books）图示改造前后，向园主推销设计方案，是近代景观设计职业化的先驱。"},{"h":"核心主张","b":"①「艺术要隐蔽」——人工痕迹越少越好；②承认适当的建筑与装饰是必要的，反对布朗的过度纯粹；③提出风景园的三要素：前景、中景、背景；④重视借景，把园外风景纳入构图。"},{"h":"与布朗的分歧","b":"布朗追求「纯粹的自然」，抹掉一切人工痕迹；雷普顿认为完全抹掉人工反而失真，主张保留适度的台地、栏杆、花坛，认为「从房子到花园的过渡」需要中介。"},{"h":"与如画派的分歧","b":"如画派（普莱斯、吉尔平）追求「粗糙、变化、不规则」的画面感，甚至主张园子应该像一幅画；雷普顿认为园林是「可居可游」的三维空间，不能只追求画面效果。"}],"q":[{"k":"名词","t":"雷普顿（Humphry Repton）","a":"18世纪末19世纪初英国造园家，布朗与如画派之间的桥梁。他以「红皮书」图示改造前后的效果，向园主推销设计方案，是近代景观设计职业化的先驱。核心主张：艺术要隐蔽，人工痕迹越少越好；但承认适当的建筑与装饰是必要的，反对布朗的过度纯粹；提出风景园的三要素（前景、中景、背景）；重视借景。他与布朗的分歧在于是否保留人工中介，与如画派的分歧在于园林是可居可游的三维空间而非单纯画面。","kp":"身份（2分）＋主张（2分）＋地位（1分）","err":"不要只写「他画红皮书」。核心是「艺术要隐蔽」与「三要素」，以及他在布朗与如画派之间的桥梁位置。"},{"k":"简答","t":"简述雷普顿的造园原则及其影响","a":"原则：①艺术要隐蔽，人工痕迹越少越好，但承认适当的建筑与装饰是必要的；②提出风景园三要素——前景、中景、背景，以此组织画面层次；③重视借景，把园外风景纳入构图；④强调从建筑到花园需要过渡中介，反对布朗的过度纯粹；⑤以「红皮书」图示改造前后，使设计意图可视化。影响：①调和了布朗的纯粹自然与如画派的画面追求，使英国风景园在19世纪仍能发展；②「红皮书」的图示方法开近代景观设计表现之先河；③三要素理论影响了后来的风景构图与景观规划；④他的职业化实践使造园从「匠作」走向「设计职业」。","kp":"原则五项（6分）＋影响四项（4分）","err":"雷普顿的「三要素」是常考点，前景/中景/背景要与风景画构图联系起来答。"}]},{"id":"c16","seq":39,"day":5,"t":"留园与网师园：苏州园林的两极","era":"c6","y":1800,"place":"苏州","lat":31.31,"lon":120.61,"tags":["留园","网师园","冠云峰","石林小院","小中见大","建筑空间"],"lead":"一个用建筑切碎空间，一个用一池水收拢全园——苏州园林的两条路走到了尽头。","pts":[{"h":"留园","b":"吴下名园之冠。以建筑空间处理见长：曲廊、漏窗、石林小院、冠云峰。东区建筑庭院、中区山水、西区山林，三区各具特色。面积约2.3公顷。"},{"h":"留园的空间手法","b":"①入口曲折幽暗，欲扬先抑；②石林小院以廊、窗、石分割，小中见大；③冠云峰为苏州园林最高大的太湖石峰；④曲廊贯穿全园，步移景异。"},{"h":"网师园","b":"苏州中小型宅园的代表，约0.54公顷。东宅西园，以彩霞池为中心，环池布置濯缨水阁、月到风来亭、看松读画轩，小中见大之极致。"},{"h":"网师园的特色","b":"①以水为中心，池面开阔而园地狭小，形成「水广园小」的错觉；②建筑贴水而建，虚实相生；③夜花园的意境（月到风来亭）。"},{"h":"两园的比较","b":"留园以「建筑空间」取胜，园大而分区明确；网师园以「水」取胜，园小而意境深远。两者代表苏州园林的两种极致。"}],"q":[{"k":"名词","t":"留园","a":"苏州四大名园之一，位于苏州阊门外留园路，明万历年间徐泰时建东园，清嘉庆年间刘恕改建，光绪年间盛康扩建并改名留园，面积约2.3公顷。以建筑空间处理见长：入口曲折幽暗、欲扬先抑；曲廊贯穿全园，漏窗借景；石林小院以廊、窗、石分割空间，小中见大；冠云峰为苏州园林最高大的太湖石峰。全园分东区建筑庭院、中区山水、西区山林，三区各具特色，被誉为「吴下名园之冠」。","kp":"沿革与位置（2分）＋空间手法（2分）＋三区与地位（1分）","err":"留园的关键词是「建筑空间处理」与「石林小院」，不要与拙政园（以水为主）混。"},{"k":"名词","t":"网师园","a":"苏州中小型宅园的代表，位于苏州葑门内阔家头巷，原为南宋史正志万卷堂故址，清乾隆年间宋宗元重建并取名「网师」（渔父），面积约0.54公顷。布局东宅西园，以彩霞池为中心，环池布置濯缨水阁、月到风来亭、看松读画轩、竹外一枝轩等，建筑贴水而建，虚实相生。池面开阔而园地狭小，形成「水广园小」的错觉，是小中见大的极致之作，被誉为苏州园林中以少胜多的典范。","kp":"沿革与规模（2分）＋布局与要素（2分）＋艺术特色（1分）","err":"网师园的关键是「小」——0.54公顷，是苏州名园中最小的之一；「水广园小」是它的核心手法。"},{"k":"绘图","t":"绘出留园平面示意，并标注三区与主要景点","a":"绘图要点：①外轮廓略呈不规则长方形，东西长、南北窄；②东区画建筑庭院，标五峰仙馆、林泉耆硕之馆、冠云峰、石林小院；③中区画山水，标水池、明瑟楼、涵碧山房、曲溪楼；④西区画山林，标土山、枫树；⑤入口在东南角，画曲折幽暗的入口通道；⑥曲廊贯穿全园；⑦标注：东区、中区、西区、冠云峰、石林小院、五峰仙馆。","kp":"三区划分（4分）＋冠云峰与石林小院（3分）＋入口处理（2分）＋曲廊（1分）","err":"留园三区的顺序是东（建筑）、中（山水）、西（山林），不要颠倒。"}],"img":"liuyuan"},{"id":"c19","seq":40,"day":5,"t":"其他园林：公共、衙署、书院","era":"c6","y":1800,"place":"中国","lat":31.3,"lon":120.62,"tags":["公共园林","衙署园林","书院园林","西湖","少数民族园林"],"lead":"除了皇家、私家、寺观，中国还有第四类园林——属于所有人，或者属于一个机构。","pts":[{"h":"公共园林","b":"①西湖：杭州西湖经唐宋历代疏浚营造，形成「西湖十景」，是中国最著名的公共园林；②鉴湖、瘦西湖等；③村口、水口的公共绿地（如徽州村落的水口园林）。"},{"h":"衙署园林","b":"官府衙署内的园林，供官员休憩、宴客，如苏州府衙、扬州衙署。规模不大，但往往有佳作。"},{"h":"书院园林","b":"书院内的园林，供学者讲学、读书、游息，如白鹿洞书院、岳麓书院。特点是清幽雅致，与文人园林相通。"},{"h":"少数民族园林","b":"藏族园林以罗布林卡为代表，融合汉藏风格；其他民族也有各具特色的园林形式。"}],"q":[{"k":"名词","t":"公共园林","a":"指由政府或公众营建、向所有人开放的园林，是中国古典园林的第四种类型（前三类为皇家、私家、寺观）。代表有杭州西湖——经唐宋历代疏浚营造，形成「西湖十景」，是中国最著名的公共园林；另有鉴湖、瘦西湖，以及徽州村落的水口园林。其特征是：服务对象为公众，功能以游赏、休憩、社交为主，规模较大，多依托自然山水。公共园林的出现说明中国园林并非只有「私享」一途，为后世城市公园提供了传统资源。","kp":"定义（2分）＋实例（2分）＋意义（1分）","err":"公共园林常被忽略，但它是中国园林四大类型之一，与皇家、私家、寺观并列。西湖是最典型的例子。"},{"k":"简答","t":"简述中国古典园林的四大类型","a":"①皇家园林：属于皇帝与皇室，规模宏大，如颐和园、避暑山庄、圆明园。②私家园林：由贵族、官僚、文人、富商营建，规模较小、小中见大，如拙政园、留园、网师园。③寺观园林：佛寺道观所属，兼具宗教与公共游憩功能，如潭柘寺、灵隐寺。④公共园林：由政府或公众营建、向所有人开放，如杭州西湖、瘦西湖、徽州水口园林。四类之中，皇家与私家是主流，寺观与公共体现了园林的社会覆盖面。这一格局在魏晋南北朝奠定，隋唐定型，明清延续。","kp":"四类各2分（8分）＋格局演变（2分）","err":"四类型是基础题，但常有人只答三类（漏掉公共园林）。西湖一定要举例。"}]},{"id":"c20","seq":41,"day":6,"t":"造园理论与匠师：从《长物志》到戈裕良","era":"c6","y":1800,"place":"江南","lat":31.3,"lon":120.62,"tags":["长物志","文震亨","闲情偶寄","李渔","戈裕良","张南垣","样式雷"],"lead":"理论家写书，匠人造园——明清的造园是「文人出主意、匠人出手艺」的合作。","pts":[{"h":"文震亨《长物志》","b":"明文震亨（文徵明曾孙）著，十二卷，记室庐、花木、水石、禽鱼、书画、几榻、器具、衣饰、香茗等。主张「宁古无时，宁朴无巧，宁俭无俗」，是文人生活美学的总纲。"},{"h":"李渔《闲情偶寄》","b":"清李渔著，其中「居室部」「器玩部」「种植部」论园林与生活美学。主张「芥子纳须弥」，以小见大；提出「取景在借」的借景理论。"},{"h":"戈裕良","b":"清代叠山名家，代表作苏州环秀山庄假山。以太湖石叠成，主峰、次峰、峡谷、洞壑一气呵成，「尺幅千里」，被誉为苏州假山第一。其技法被称为「钩带法」，使假山浑然一体。"},{"h":"张南垣","b":"明末清初叠山家，主张「以少胜多」，反对堆砌，开创「土石相间」的叠山风格，影响清代造园。"},{"h":"样式雷","b":"清代皇家建筑世家，主持圆明园、颐和园、避暑山庄等皇家园林的规划设计，留下大量「画样」（图纸）与「烫样」（模型），是清代皇家园林营建的核心技术力量。"}],"q":[{"k":"名词","t":"《长物志》","a":"明代文震亨（文徵明曾孙）所著，十二卷，分室庐、花木、水石、禽鱼、书画、几榻、器具、衣饰、香茗等门类，是文人生活美学的总纲。其造园主张为「宁古无时，宁朴无巧，宁俭无俗」，强调古雅、朴素、简练，反对富丽与繁缛。它把居室、花木、器具、赏石纳入完整的文人生活体系，与《园冶》《闲情偶寄》共同构成明清造园理论体系，是研究文人园林审美的重要文献。","kp":"作者与体例（2分）＋主张（2分）＋地位（1分）","err":"作者是文震亨（文徵明曾孙），不要与文徵明本人混；《长物志》偏生活美学，《园冶》偏造园技术。"},{"k":"名词","t":"戈裕良","a":"清代叠山名家，代表作苏州环秀山庄假山。他以太湖石叠成，主峰、次峰、峡谷、洞壑一气呵成，「尺幅千里」，被誉为苏州假山第一。其技法被称为「钩带法」——石块之间以钩带相连，使假山浑然一体、不见拼接痕迹。他主张叠山应「如画」，以画理立意、以皴法造型，是「匠而能主」的典型：技艺到了极处，本身就含着立意。环秀山庄假山是清代叠山艺术的巅峰之作。","kp":"身份与代表作（2分）＋技法（2分）＋评价（1分）","err":"戈裕良的关键词是「钩带法」与「尺幅千里」，代表作是环秀山庄（不是留园、拙政园）。"},{"k":"论述","t":"试论明清造园理论的体系构成","a":"一、三部核心著作。①计成《园冶》（1631）：中国第一部系统的造园专著，讲兴造论、相地、立基、掇山、借景，核心命题是「虽由人作，宛自天开」「巧于因借，精在体宜」。②文震亨《长物志》：十二卷，讲室庐、花木、水石、器具，主张「宁古无时，宁朴无巧，宁俭无俗」，是文人生活美学的总纲。③李渔《闲情偶寄》：居室部、种植部论园林，主张「芥子纳须弥」「取景在借」。二、三者的分工。《园冶》讲「怎么造」——技术、方法、程序；《长物志》讲「造什么」——品味、格调、器物；《闲情偶寄》讲「怎么用」——生活、情趣、借景。三者合起来，构成从技术到美学到生活的完整体系。三、匠师的实践。张南垣主张「以少胜多」「土石相间」，戈裕良以「钩带法」叠环秀山庄，样式雷主持皇家园林营建——理论由文人提出，技艺由匠人实现，二者合作才有明清园林的高度。四、历史意义。这套理论体系使中国园林从「匠作」提升为「艺术」，也使造园经验得以传承；但它也带来了程式化的隐患——当理论变成教条，创新就停止了。结论：明清造园理论是中国园林的「自我总结」，它既是巅峰的标志，也是固化的开始。","kp":"三部著作（6分）＋分工（4分）＋匠师（3分）＋意义（3分）","err":"不要把三部书混为一谈。《园冶》是技术、《长物志》是品味、《闲情偶寄》是生活，分工要讲清。"}]},{"id":"c21","seq":42,"day":6,"t":"中国园林的美学总纲","era":"c6","y":1800,"place":"中国","lat":31.3,"lon":120.62,"tags":["本于自然","高于自然","建筑融糅","诗画情趣","意境","虽由人作宛自天开"],"lead":"如果说前面都是「史」，这一站是「论」——中国园林到底美在哪里。","pts":[{"h":"四大特点","b":"①本于自然、高于自然：以自然山水为蓝本，但经过概括、提炼、典型化，用「一拳代山、一勺代水」的写意手法再现山水，达到「虽由人作，宛自天开」。②建筑美与自然美的融糅：亭台楼阁榭舫与山水花木有机结合，建筑依山就势、因水而设，成为自然景观的有机部分。③诗画的情趣：以诗入园、以画入园，立意构思、景点命名、楹联匾额富文学意味。④意境的蕴涵：通过借景、障景、框景、对景，使有限空间生发无限联想。"},{"h":"手法的程式化","b":"叠山、理水、建筑、植物四大要素成熟定型，形成「小中见大、步移景异、欲扬先抑、曲折有法、以廊串景」的稳定手法体系。"},{"h":"与西方园林的根本差异","b":"①本于自然、高于自然 vs 强迫自然接受匀称的法则；②建筑与自然融糅 vs 建筑控制自然或退避三舍；③诗画情趣与意境 vs 几何秩序与透视；④写意 vs 写实。"},{"h":"意境的三层","b":"①物境：景物的形、色、声；②情境：景物引发的情感；③意境：超越景物的人生感悟。三层递进，是中国园林的最高追求。"}],"q":[{"k":"简答","t":"简述中国古典园林的四大特点","a":"①本于自然、高于自然：以自然山水为蓝本，但不是简单模仿，而是经过概括、提炼、典型化，用「一拳代山、一勺代水」的写意手法再现山水，最终达到「虽由人作，宛自天开」的境界，这是中国园林最本质的特征。②建筑美与自然美的融糅：亭、台、楼、阁、榭、舫与山水花木有机结合，建筑依山就势、因水而设，以轻盈通透的木构架、灰瓦白墙融入自然，使人工建筑成为自然景观的有机部分。③诗画的情趣：以诗入园、以画入园，园林的立意构思、景点命名、楹联匾额都富文学意味，空间经营讲究起承转合与画意。④意境的蕴涵：通过借景、障景、框景、对景等手法，使有限空间生发无限联想。","kp":"四点各2分（8分）＋总述（2分）","err":"四点要能默写。「本于自然、高于自然」是第一点，也是最本质的一点，必须放在最前面。"},{"k":"论述","t":"比较中国古典园林与西方古典园林的美学差异","a":"一、自然观不同。中国是「天人合一」——人不是自然的征服者，而是自然的参与者，所以造园追求「虽由人作，宛自天开」；西方是「人定胜天」——法国古典主义主张「强迫自然接受匀称的法则」，把自然改造成几何。二、建筑与自然的关系不同。中国园林把建筑融糅于山水花木之中，建筑依山就势、因水而设，是自然的有机部分；西方园林要么让建筑控制一切（法国轴线），要么让建筑退避三舍（英国风景园），两者都把建筑与自然对立起来。三、空间观念不同。中国园林是「小中见大」——用有限空间生发无限联想，讲究「步移景异」「曲折有法」；西方园林是「以大见大」——用轴线、透视、大运河制造无限纵深，讲究「一眼望穿」。四、审美目标不同。中国追求「意境」——景外之情、言外之意；西方追求「秩序」——比例、对称、统一。五、共同点。两者都追求人工与自然的和谐，只是路径不同：中国是「融入」，西方是「控制」。结论：中西园林的差异，本质是两种宇宙观的差异——中国相信人与自然是一体的，西方相信人应当主宰自然。这一差异至今仍在影响东西方的景观设计。","kp":"自然观（3分）＋建筑关系（3分）＋空间（3分）＋审美（2分）＋共同点（1分）","err":"不要写成「中国好西方不好」。核心是「融入 vs 控制」两种宇宙观的差异，这个判断要不偏不倚。"}]},{"id":"w21","seq":43,"day":6,"t":"近现代：城市公园运动","era":"w8","y":1858,"place":"纽约","lat":40.78,"lon":-73.97,"tags":["城市公园","伯肯海德","中央公园","奥姆斯特德","阿尔方","国家公园"],"lead":"工业城市的烟囱逼出了公园——园林第一次成为公共卫生问题，而不只是贵族享乐。","pts":[{"h":"伯肯海德公园","b":"1847年，世界第一座真正意义上的城市公园，帕克斯顿设计，位于利物浦。为工业城市的工人提供游憩空间，成为各国城市公园运动效仿的样板。"},{"h":"纽约中央公园","b":"1858年，奥姆斯特德与沃克斯设计，开创「景观设计」职业。以自然式风景回应城市，是城市公园运动的里程碑。"},{"h":"巴黎改造","b":"拿破仑三世与奥斯曼改造巴黎，阿尔方负责布劳涅林苑与万森纳林苑的整治：开挖人工湖（圣芒德湖、多麦斯尼尔湖）、设置散步道与绿化处、以泵站供水。万森纳林苑设动物园（1934年开放）、126000棵树木。"},{"h":"19世纪园林特征","b":"①服务对象从贵族转向公众；②功能从观赏转向游憩与公共卫生；③设计从几何转向自然式；④职业化：出现职业景观设计师（奥姆斯特德）；⑤类型扩展：城市公园、国家公园（美国黄石）。"}],"q":[{"k":"名词","t":"城市公园运动","a":"19世纪中叶起源于英国、遍及欧美的公共绿地建设运动。工业革命后城市人口激增、卫生恶化，工人阶级需要户外游憩空间，于是出现由政府或公共机构建设、向所有人开放的城市公园。标志性作品为1847年利物浦伯肯海德公园（帕克斯顿设计，世界第一座真正意义上的城市公园）与1858年纽约中央公园（奥姆斯特德与沃克斯设计）。运动使园林的服务对象从贵族转向公众，功能从观赏转向游憩与公共卫生，并催生了「景观设计」这一职业。","kp":"背景（2分）＋标志作品（2分）＋意义（1分）","err":"不要把「城市公园」与「国家公园」混。前者服务城市居民日常游憩，后者保护自然遗产（黄石1872）。"},{"k":"论述","t":"试论19世纪城市公园运动兴起的原因与影响","a":"一、原因。①工业革命与城市化：人口急剧涌入城市，居住密度过高，卫生条件恶化，传染病频发；②公共卫生观念：医生与改革者认为新鲜空气与绿地是健康必需品，公园被当作「城市的肺」；③社会矛盾：工人阶级缺乏体面的休闲场所，酒馆与街头成为社会问题，公园被视为「道德改良」的工具；④政治因素：统治者希望通过公共设施缓和社会矛盾；⑤美学与思想：浪漫主义与自然崇拜使自然式风景成为理想。二、标志与人物。1847年伯肯海德公园（帕克斯顿）是世界第一座真正意义的城市公园；1858年纽约中央公园（奥姆斯特德与沃克斯）确立范式，并开创「景观设计」职业；巴黎的奥斯曼改造与阿尔方的林苑整治提供了另一种模式（国家主导、成体系布局）。三、影响。①园林服务对象从贵族转向公众，功能从观赏转向游憩与公共卫生；②设计语言从几何规则式转向自然式；③催生职业景观设计师与城市规划学科；④类型扩展：城市公园、林苑、国家公园（美国黄石1872）；⑤为20世纪的城市绿地系统规划奠定基础。结论：城市公园运动是园林史上第一次「社会性转向」，它把园林从艺术品变成了公共基础设施。","kp":"原因五项（6分）＋标志与人物（5分）＋影响五项（5分）","err":"原因要答「卫生＋社会＋政治」三层，只答「工业污染」太单薄；影响要落到「社会性转向」这个判断上。"},{"k":"绘图","t":"绘出纽约中央公园平面示意，并标注主要景区","a":"绘图要点：①外轮廓为规整的长方形（嵌入曼哈顿方格网）；②园内以自然式布局，画大片草地、蜿蜒水面、树丛；③标中央湖（The Lake）、大草坪（Great Lawn）、杰奎琳·肯尼迪·奥纳西斯水库；④园内道路为曲线，与外部的方格网形成对比；⑤标注：中央湖、大草坪、水库、曲线园路。","kp":"规整外轮廓（2分）＋自然式内部（4分）＋主要景区（2分）＋内外对比（2分）","err":"中央公园的精髓是「规整边界＋自然内部」的对比，只画自然式而忘了外面是方格网，就丢了要点。"}],"img":"birkenhead"},{"id":"w24","seq":44,"day":6,"t":"美国：国家公园与景观设计职业","era":"w8","y":1872,"place":"黄石","lat":44.6,"lon":-110.5,"tags":["美国","国家公园","黄石","奥姆斯特德","景观设计"],"lead":"美国人把「公园」放大到一整个荒野——国家公园是园林史上最大尺度的作品。","pts":[{"h":"国家公园","b":"1872年黄石国家公园建立，是世界上第一个国家公园。它把「保护自然遗产」作为目标，与城市公园的「服务市民游憩」不同。"},{"h":"奥姆斯特德","b":"美国景观设计之父。1858年与沃克斯设计纽约中央公园，开创「景观设计」（Landscape Architecture）职业；此后设计波士顿「翡翠项链」公园系统，提出城市绿地系统的概念。"},{"h":"美国园林的特点","b":"①尺度大：国家公园、州级公园、城市公园体系；②功能复合：游憩、生态保护、教育；③职业化：景观设计师成为独立职业；④理论：奥姆斯特德的「风景如画」与「社会改良」并重。"},{"h":"影响","b":"美国的国家公园制度被全世界效仿；景观设计职业化影响了20世纪的园林与城市规划。"}],"q":[{"k":"名词","t":"国家公园","a":"指为保护自然遗产、供公众游憩与教育而划定的大面积自然区域。1872年美国建立黄石国家公园，是世界上第一个国家公园。它与城市公园不同：城市公园服务于市民日常游憩，国家公园以保护原始自然生态与地质奇观为目标，尺度极大，管理上强调「保护优先」。国家公园制度后来被全世界效仿，成为自然保护与公共游憩结合的重要制度发明，也是园林从「造园」扩展到「大地景观」的标志。","kp":"定义（2分）＋黄石（2分）＋与城市公园的区别（1分）","err":"不要与国家公园「城市公园」混。前者保护自然遗产（黄石1872），后者服务市民游憩（伯肯海德1847）。"},{"k":"论述","t":"试论奥姆斯特德对现代景观设计的贡献","a":"一、开创职业。1858年奥姆斯特德与沃克斯合作设计纽约中央公园，在竞赛中获胜，此后「景观设计」（Landscape Architecture）逐渐成为独立职业，奥姆斯特德被称为「美国景观设计之父」。二、确立范式。中央公园以自然式风景回应城市，用大片草地、蜿蜒水面、树丛与步道，在曼哈顿的方格网中造出一片「田园」，成为城市公园的世界范式。三、提出系统观。他设计波士顿「翡翠项链」公园系统，用绿道串联多个公园与水系，第一次提出「城市绿地系统」的概念——公园不再是孤立的一块地，而是城市基础设施的一部分。四、社会理想。奥姆斯特德认为公园是「民主的场所」，不同阶层的人可以在自然中相遇，公园具有社会改良的功能。这一思想影响了后来的城市公园运动与公共空间理论。五、尺度扩展。从城市公园到区域规划，奥姆斯特德的工作把园林从「造园」推向「景观规划」，为20世纪的区域规划与生态规划奠定基础。结论：奥姆斯特德的贡献不只是设计了几个公园，而是创造了「景观设计」这个职业与「绿地系统」这个观念。","kp":"开创职业（3分）＋确立范式（3分）＋系统观（3分）＋社会理想（2分）＋尺度扩展（2分）","err":"不要只写「他设计了中央公园」。核心是「职业化」与「系统观」两项制度性贡献。"}]},{"id":"c17","seq":45,"day":6,"t":"清末：程式化与衰落","era":"c6","y":1880,"place":"中国","lat":31.3,"lon":120.62,"tags":["清末","程式化","衰落","岭南园林","余荫山房"],"lead":"当造园变成了「照规矩做」，中国古典园林就走到了它的终点。","pts":[{"h":"程式化的表现","b":"①手法定型：叠山、理水、建筑、植物四大要素形成固定套路；②题材重复：常见的「四季」「八景」「十景」成为模板；③意境空洞：题名与景致脱节，流于文字游戏；④过度装饰：建筑繁复、堆砌，失去疏朗之气。"},{"h":"衰落的原因","b":"①社会动荡：战乱、经济衰退，造园财力不足；②文化僵化：科举僵化、思想禁锢，文人精神萎缩；③西风东渐：西方建筑与造园手法进入，传统体系受冲击；④园林功能变化：从文人私享转向公众游览，审美取向改变。"},{"h":"岭南园林","b":"余荫山房、可园、清晖园、梁园，以「藏而不露、缩龙成寸」见长，装饰繁丽（灰塑、木雕、彩色玻璃），空间精巧，是清末地方风格的代表。"},{"h":"历史的辩证","b":"清末园林的程式化不是「变差」，而是「体系成熟到极致后的固化」。它把中国园林的全部手法浓缩成可复制的模板，这既是成就，也是终点。"}],"q":[{"k":"论述","t":"试论中国古典园林在清末的程式化与衰落","a":"一、程式化的表现。①手法定型：叠山、理水、建筑、植物四大要素形成固定套路，叠山必太湖石、理水必池中设岛、建筑必亭台楼阁；②题材重复：「四季」「八景」「十景」成为模板，个园的四季假山是程式化的巅峰也是极限；③意境空洞：题名与景致脱节，流于文字游戏，园林的「诗画情趣」变成装饰；④过度装饰：建筑繁复、堆砌，失去疏朗之气。二、衰落的原因。①社会动荡：战乱与经济衰退使造园财力不足；②文化僵化：科举僵化、思想禁锢，文人精神萎缩，园林失去思想支撑；③西风东渐：西方建筑与造园手法进入，传统体系受冲击；④功能变化：从文人私享转向公众游览，审美取向改变。三、历史的辩证。程式化不是「变差」，而是「体系成熟到极致后的固化」——它把中国园林的全部手法浓缩成可复制的模板，这既是成就，也是终点。四、启示。今天的园林设计仍面临同样的问题：当手法成为套路，创新从哪里来？答案或许在于重新回到「相地」与「因借」——从场地本身出发，而不是从模板出发。结论：清末的衰落不是中国园林的失败，而是一个成熟体系的自然终结，它为现代园林的转型提供了反思的起点。","kp":"程式化四项（6分）＋衰落原因四项（6分）＋辩证（2分）＋启示（2分）","err":"不要简单说「清末园林不好」。核心判断是「成熟到极致后的固化」，这个辩证关系是得分关键。"},{"k":"名词","t":"岭南园林","a":"中国古典园林的地方流派之一，分布于广东一带，代表为余荫山房、可园、清晖园、梁园（岭南四大名园）。特征：①「藏而不露、缩龙成寸」——用地狭小，以廊桥、水池、花木在有限空间内层层展开；②装饰繁丽——灰塑、木雕、彩色玻璃（满洲窗）、陶塑脊饰大量使用；③空间精巧——建筑密度高，以冷巷、天井组织通风；④中西合璧——受南洋与西方影响，出现拱券、彩色玻璃等元素。它是清末地方风格的代表，体现了岭南气候、商业文化与外来影响的三重作用。","kp":"流派与代表（2分）＋特征（2分）＋成因（1分）","err":"岭南园林的关键词是「藏而不露、缩龙成寸」与「装饰繁丽」，与江南园林的疏朗雅致形成对比。"}]},{"id":"w25","seq":46,"day":6,"t":"19世纪园林的总特征","era":"w8","y":1900,"place":"欧美","lat":50.0,"lon":-10.0,"tags":["19世纪","折衷主义","城市公园","职业化","风景式"],"lead":"19世纪的园林没有统一的风格——它把历史上所有的风格都拿来用了一遍。","pts":[{"h":"折衷主义","b":"19世纪园林风格多元：规则式（法国）、风景式（英国）、意大利式、伊斯兰式并存，设计师按业主要求与场地条件选择，不再有「唯一正确」的风格。"},{"h":"城市公园运动","b":"城市公园大量兴建，服务对象从贵族转向公众，功能从观赏转向游憩与公共卫生。"},{"h":"职业化","b":"出现职业景观设计师（奥姆斯特德）、职业造园师，园林从「匠作」变成「职业」。"},{"h":"技术与材料","b":"玻璃温室（邱园棕榈室）、钢铁结构、新植物材料（从殖民地引种）改变了园林的面貌。"}],"q":[{"k":"简答","t":"简述19世纪西方园林的主要特征","a":"①折衷主义：规则式、风景式、意大利式、伊斯兰式并存，设计师按业主要求与场地条件选择，不再有唯一正确的风格。②城市公园运动：城市公园大量兴建，服务对象从贵族转向公众，功能从观赏转向游憩与公共卫生。③职业化：出现职业景观设计师（奥姆斯特德）与职业造园师，园林从匠作变成职业。④技术与材料：玻璃温室（邱园棕榈室）、钢铁结构、从殖民地引种的新植物材料改变了园林面貌。⑤尺度扩展：从私家园林扩展到城市公园、国家公园、区域规划。⑥影响：为20世纪现代园林与景观规划奠定基础。","kp":"五点特征（10分）","err":"19世纪的关键词是「折衷」与「职业化」。不要把它写成「英国风景园的延续」，19世纪的园林已经多元化了。"}]}]};
